INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','monumento','Provincia de Ciudad Real','Completada al 100% (Cerrado tras Villarta de San Juan).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','monumento','Provincia de Albacete','Completada al 100% (Cerrado tras Yeste).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','monumento','Provincia de Castellón','Completada al 100% (135 municipios, cerrado tras Zucaina).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','monumento','Provincia de Valencia','Completada al 100% (266 municipios, cerrado estrictamente tras Zarra).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','monumento','Próxima provincia sugerida para la Hoja de Ruta','Provincia de Alicante (último paso natural para culminar de forma lógica el bloque geográfico completo de la Comunidad Valenciana).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Alicante, Letra A (comenzando estrictamente por municipios como L''Atzúbia, Agres, Alcoi / Alcoy, Alacant / Alicante Capital, Alfafara, etcétera).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90378','iglesia','Santuario de la Virgen del Castillo','Espectacular complejo religioso del siglo XV profundamente reformado en el barroco, emplazado de forma monumental sobre las ruinas de una fortaleza medieval en la cima de un escarpado risco de la Sierra de Mariola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90378','monumento','Neveras de la Sierra de Mariola (Cava Gran)','Extraordinario conjunto de ingeniería etnológica tradicional de los siglos XVII y XVIII constituido por colosales pozos de nieve circulares de sillería caliza calavera rematados por arquerías de piedra exentas destinados al comercio histórico del hielo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90379','iglesia','Iglesia Parroquial de Santiago Apóstol','Monumental fábrica barroca del siglo XVIII de proporciones herrerianas en la comarca de la Vega Baja que exhibe una fastuosa portada monumental plateresca de ricas molduras escultóricas talladas en piedra caliza calavera y un interior columnario cubierto por una gran cúpula.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90380','monumento','Torre de Alcalalí (Torre Medieval)','Recia estructura defensiva y atalaya de vigilancia bajomedieval del siglo XIV dispuesta en el casco urbano, construida mediante aparejo de sillería regular y mampostería basta que conserva sus matacanes defensivos y saeteras intactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90380','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVIII de líneas barroco-clasicistas edificado en mampostería encintada que aloja un presbiterio cubierto por bóveda de cañón con lunetos y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','monumento','Conjunto Modernista de Alcoy (Casa del Pavo / Círculo Industrial)','Espectacular y suntuoso patrimonio civil e industrial de principios del siglo XX que exhibe fachadas monumentales caladas por intrincadas filigranas de hierro forjado, miradores calados de madera, azulejería y decoraciones de la escuela modernista valenciana de valor universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','monumento','Viaducto de Canalejas y Puente de San Jorge','Colosales estructuras de ingeniería civil e hidráulica tradicionales de sillería y acero de gran sección erigidas sobre los profundos barrancos fluviales que jalonan de forma monumental el trazado de la expansión urbana industrial de la ciudad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','iglesia','Iglesia de Santa María','Monumental fábrica barroca del siglo XVIII reedificada en el siglo XX siguiendo las líneas del clasicismo académico en cantería de primer orden que presenta una espaciosa planta basilical sostenida por pilares toscanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','monumento','Yacimiento de La Sarga','Abrigos naturales rocosos protegidos por la UNESCO que conservan centenares de figuras pictóricas de arte rupestre levantino, esquemático y macroesquemático grabadas con óxidos de hierro rojos por comunidades prehistóricas de la máxima relevancia nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','iglesia','Iglesia Parroquial de la Transfiguración del Señor','Templo del siglo XVI con importantes reformas barrocas edificado en el tradicional aparejo de cajones de mampostería caliza de la Sierra de Mariola que alberga una nave única con una robusta torre campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','monumento','Les Cueves de les Finestres','Singular e histórico complejo arqueológico y troglodítico tallado directamente de forma monumental en una vertiginosa pared rocosa caliza, consistente en ventanas labradas a pico que comunican con estancias destinadas históricamente a silos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','monumento','Castillo de Álora','Espectacular y colosal complejo fortificado medieval de origen andalusí de los siglos IX y X erigido en sillería de cantería caliza regular y mampostería basta sobre un escarpado cerro testigo que domina el Valle del Guadalhorce, el cual conserva de forma monumental su alcazaba, una espectacular torre de la vela, lienzos almenados y el único arco de herradura califal exento intacto de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','iglesia','Iglesia Parroquial de Nuestra Señora de la Encarnación','Magna obra columnaria barroca del siglo XVII construida en cantería caliza calavera de primer orden que exhibe tres naves de colosales proporciones de gran luz espacial separadas por pilares toscanos de gran sección y una robusta torre campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','iglesia','Convento de la Virgen de las Flores','Complejo religioso barroco del siglo XVIII levantado en el entorno periurbano mediante aparejo mixto que destaca por albergar en su iglesia un camarín absidial ricamente decorado con yeserías polícromas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90381','iglesia','Iglesia Parroquial de los Santos de la Piedra','Humilde oratorio de la comarca del Vinalopó Medio edificado en mampostería tosca encalada en el siglo XIX que cuenta con una pequeña espadaña de ladrillo visto de un solo vano y cubiertas de yesería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','monumento','Castillo de Santa Bárbara','Inmenso e inexpugnable complejo fortificado que corona de forma monumental la cima del monte Benacantil dominando la fachada marítima en sillería de cantería regular caliza y mampostería basta, el cual conserva vestigios andalusíes unidos a potentes murallas almenadas renacentistas, fosos y el Baluarte de la Mina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','catedral','Concatedral de San Nicolás de Bari','Monumental fábrica de transición renacentista y herreriana del siglo XVII construida en sillería caliza calavera que exhibe una nave única de colosales proporciones de gran luz espacial cubierta por una colosal cúpula sobre el crucero de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','iglesia','Basílica de Santa María','El templo más antiguo de la capital, datado en el siglo XIV de estilo gótico valenciano y portada monumental barroca churrigueresca profusamente esculpida con columnas salomónicas de mármol polícromo por Juan Bautista Borja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','palacio','Palacio Municipal (Ayuntamiento)','Obra cumbre de la arquitectura civil barroca valenciana del siglo XVIII que presenta una fachada palaciega de sillería de piedra de primer orden flanqueada por dos robustas torres campanario gemelas de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','iglesia','Monasterio de la Santa Faz','Complejo religioso barroco del siglo XVIII levantado en el entorno periurbano','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90382','iglesia','Iglesia Parroquial de San Andrés Apóstol','Edificio de lines neoclásicas construido en el siglo XIX tras el catastrófico terremoto de Torrevieja mediante el tradicional aparejo mixto que aloja un presbiterio con bóveda de arista y una robusta torre campanario de planta cuadrada baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90383','monumento','Torre de Almudaina','Recia torre defensiva de origen andalusí de planta cuadrada erigida en sillería caliza regular y mampostería basta en el núcleo del casco histórico de la comarca del Comtat que servía como alquería fortificada y puesto de vigilancia territorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','iglesia','Iglesia Parroquial de Nuestra Señora del Consuelo','Monumental templo del siglo XIX conocido como la "Cúpula del Mediterráneo" por sus imponentes proporciones barroco-clasicistas que destaca por su colosal cúpula central sobre el crucero decorada con una inconfundible azulejería vidriada azul y blanca exenta de gran impacto visual.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','monumento','Torre de la Galera','Recia estructura defensiva bajomedieval de planta circular construida mediante aparejo de mampostería basta y esquinales de sillería labrada que servía como torre vigía costera contra la piratería berberisca de la Marina Baixa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03005','iglesia','Iglesia Parroquial de Nuestra Señora del Socorro','Monumental fábrica barroca de transición neoclásica del siglo XVIII erigida en sillería caliza calavera de primer orden, destacando su espectacular fachada-retablo profusamente esculpida y un interior columnario de amplia nave única cubierto por una colosal cúpula sobre el crucero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03005','monumento','Castillo del Río','Ruinas de una importante fortaleza militar de origen andalusí de los siglos XII y XIII de la que subsisten potentes lienzos de muralla fortificados de tapial y mampostería basta adaptados al perfil geológico del terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90384','iglesia','Iglesia Parroquial de San Francisco de Asís','Templo rural del Comtat edificado en mampostería basta encalada que cuenta con una pequeña espadaña de ladrillo visto de dos ojos y un interior con bóvedas de arista enfoscadas en yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90385','monumento','Núcleos de población de Benasau','El término municipal incluye los siguientes núcleos de población: Ares del Bosque.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90385','palacio','Torre de Benasau (Palacio de los Marqueses de Malferit)','Casona señorial fortificada de origen bajomedieval construida en sillería de piedra de la que destaca su recia torre defensiva de planta cuadrada y un patio porticado central de gran valor etnológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90385','iglesia','Iglesia Parroquial de San Pedro Apóstol','Fábrica barroca del siglo XVIII levantada con paramentos de mampostería encintada que aloja un presbiterio con bóveda de cañón con lunetos y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90386','iglesia','Iglesia Parroquial de la Virgen del Rosario','Templo de la comarca de la Vega Baja reconstruido tras los terremotos históricos con paramentos de aparejo mixto de piedra y ladrillo visto que presenta una fachada neoclásica sobria flanqueada por dos torres campanario bajas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90387','iglesia','Iglesia Parroquial de San Jerónimo','Edificio de culto de la Vega Baja levantado en el siglo XVIII con aparejo mixto de piedra y ladrillo que cuenta con una pequeña torre campanario y cubiertas de bóveda de arista modesta de líneas neoclásicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90388','iglesia','Iglesia Parroquial de San Juan Bautista','Fábrica del siglo XVIII de líneas barroco-clasicistas edificada mediante el tradicional aparejo mixto de mampostería de la Marina Alta y hiladas de ladrillo visto macizo que aloja una nave única con un campanario bajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90389','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del Valle de Guadalest edificado en el siglo XVIII mediante el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que aloja una nave única reformada en el barroco y un artesonado sencillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90390','iglesia','Iglesia Parroquial de San Pedro Apóstol','Fábrica del siglo XVI de líneas renacentistas y transición barroca construida en sillería caliza en sus esquinales y mampostería ordinaria del Comtat que destaca por su ábside poligonal gótico tardío reforzado por recios contrafuertes y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90391','monumento','Cueva de las Calaveras','Cavidad natural caliza de trascendencia universal por su valor prehistórico y arqueológico que conserva vestigios de ocupación humana que abarcan desde el Paleolítico Medio hasta la Edad del Bronce con un importante yacimiento paleontológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90391','iglesia','Iglesia Parroquial de la Sangre de Cristo','Fábrica barroca del siglo XVIII de la Marina Alta levantada con el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que resguarda una nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','iglesia','Iglesia Parroquial de San Jaime Apóstol y Santa Ana','Templo barroco del siglo XVIII levantado en el casco','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','monumento','Torre de las Caletas / Torre de Les Caletes','Ruinas de una torre vigía costera del siglo XVI erigida en sillería y mampostería sobre el acantilado para la defensa de la línea de costa contra la piratería berberisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90392','monumento','Castillo de Benifallim / El Castellot','Ruinas de una atalaya militar defensiva de origen andalusí emplazada de forma espectacular sobre un promontorio rocoso de l''Alcoià de la que restan potentes lienzos de muralla de mampostería basta y la base de su gran torre del homenaje de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90392','iglesia','Iglesia Parroquial de San Miguel Arcángel','Fábrica barroca del siglo XVIII levantada con paramentos de mampostería encintada que aloja un presbiterio con bóveda de cañón con lunetos y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90393','iglesia','Iglesia Parroquial de San Miguel Arcángel','Modesta edificación de culto de la comarca del Valle de Guadalest levantada con cajones de mampostería ordinaria y esquinales de sillería caliza que cuenta con una pequeña torre campanario de dos cuerpos y cubiertas de yesería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90394','iglesia','Iglesia Parroquial de San José','Templo rural de la Marina Alta edificado en mampostería basta encalada que cuenta con una pequeña espadaña de ladrillo visto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90395','iglesia','Iglesia Parroquial de Santiago Apóstol','Fábrica del siglo XVIII de líneas renacentistas sencillas construida en aparejo de mampostería de la comarca de la Vega Baja que alberga una bóveda de cañón rebajada sobre el presbiterio y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90396','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Fábrica del siglo XVIII de estilo barroco academicista construida en cantería del Comtat que destaca por albergar una espaciosa nave central cubierta por bóvedas de cañón con lunetos y un campanario de planta cuadrada baja con remates de piedra tosca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90397','iglesia','Iglesia Parroquial de la Virgen del Rosario','Humilde oratorio de la comarca del Comtat edificado en mampostería tosca encalada que cuenta con una pequeña espadaña de ladrillo visto de un solo vano y cubiertas de yesería enfoscadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90398','iglesia','Iglesia Parroquial de San Vicente Mártir','Edificio de culto del siglo XVIII construido en el Valle de Guadalest mediante el tradicional aparejo mixto de mampostería basta y verdugadas de ladrillo visto que presenta una fachada neoclásica y una torre campanario con remates de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90399','iglesia','Iglesia Parroquial de Santa Ana','Fábrica barroca del siglo XVIII de la comarca del Comtat levantada con el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que resguarda una nave única techada por una estructura de bóveda de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90400','iglesia','Iglesia Parroquial de San Andrés Apóstol','Fábrica del siglo XVIII de líneas renacentistas sencillas construida en aparejo de mampostería de la Marina Alta que alberga una bóveda de cañón rebajada sobre el presbiterio y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03042','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo barroco del siglo XVIII levantado con recios muros de mampostería encintada de la Marina Alta que alberga una nave única con crucero rematado por una esbelta cúpula sobre pechinas decorada con azulejería vidriada de tradición levantina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03043','monumento','Castillo de Biar','Espectacular e imponente fortaleza medieval del siglo XII de origen andalusí y posterior señorío cristiano que corona la silueta de la montaña en la comarca del Alto Vinalopó, construida en sillería y mampostería basta que conserva una colosal torre del homenaje que alberga en su interior una de las bóvedas de crucería de estilo almohade más antiguas e importantes de España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03043','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental fábrica tardogótica del siglo XV reformada en el renacimiento plateresco con cantería caliza calavera de primer orden, destacando su espectacular portada plateresca labrada con relieves iconográficos y un interior columnario con bóvedas estrelladas y la fastuosa capilla barroca de la Comunión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03043','monumento','Acueducto de Biar','Monumental obra de ingeniería civil e hidráulica medieval del siglo XV construida en sillería de cantería y ladrillo visto que salva los desniveles del barranco mediante una arquería mixta de arcos apuntados y de medio punto bien conservados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03044','iglesia','Iglesia Parroquial of Nuestra Señora de la Merced','Edificio de culto de la comarca de la Vega Baja levantado con cajones de mampostería encintada y hiladas de ladrillo visto macizo que presenta una fachada barrococlasicista rematada por un frontón y una robusta torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03046','monumento','Castillo de Busot','Ruinas consolidadas de una antigua fortaleza militar de origen andalusí de planta cuadrangular erigida en mampostería basta y tapial sobre el cerro que domina la población, conservando lienzos de murallas defensivas y restos de la torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03046','monumento','Cuevas de Canelobre','Inmensa cavidad natural caliza de trascendencia universal por sus colosales dimensiones espaciales que alberga una de las bóvedas subterráneas más altas de España ornada por caprichosas formaciones geológicas de estalagmitas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03049','iglesia','Iglesia de San Martín','Obra cumbre de la arquitectura columnaria gótico-renacentista de la Vega Baja construida en el siglo XVI en sillería caliza de primer orden que exhibe tres naves de colosales proporciones de gran luz espacial sustentadas por robustos pilares jónicos y una espectacular portada barroca clasicista herreriana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03049','iglesia','Santuario de San Roque','Complejo barroco de proporciones monumentales erigido en cantería sobre la falda de la sierra local que presenta una majestuosa fachada de suntuosa decoración escultórica y un interior que alberga un camarín absidial ricamente decorado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03048','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental templo del siglo XVIII de estilo barroco academicista erigido en cantería caliza calavera y ladrillo de la Marina Baixa que destaca por su espaciosa nave central cubierta por bóvedas de cañón, una gran cúpula sobre el crucero y un campanario exento de planta cuadrada provista de remates de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03048','monumento','Murallas de Callosa y Portal de la Font','Vestigios del recinto fortificado medieval del siglo XIV del que se conserva de forma monumental un torreón-puerta de sillería regular provisto de un gran arco de medio punto dovelado que servía como puerta de acceso principal a la villa fortificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03052','monumento','Castalla','Castalla','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','monumento','Abrigo de arte rupestre de Pla de Petracos','Conjunto arqueológico universal protegido por la UNESCO que conserva de forma monumental excepcionales muestras de arte rupestre macroesquemático y neolítico pintadas con óxidos de hierro rojos sobre abrigos calizos de la Marina Alta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','iglesia','Iglesia Parroquial de Santa Ana','Templo del siglo XVIII de líneas barroco-clasicistas edificado en mampostería encintada que aloja un presbiterio cubierto por bóveda de cañón con lunetos y una torre campanario baja de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03045','iglesia','Iglesia Parroquial de San José','Modesta edificación de culto de la comarca de la Marina Baixa levantada con cajones de mampostería ordinaria y esquinales de sillería caliza que cuenta con una pequeña torre campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03011','monumento','Castillo de Castalla','Espectacular y colosal complejo fortificado medieval de los siglos XIII y XIV erigido en sillería de cantería caliza regular de primer orden sobre un escarpado cerro testigo de la comarca de la Hoya de Castalla, el cual conserva de forma monumental su torre del homenaje de planta cuadrada conocida como de Grossa, lienzos almenados y el palacio residencial interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03011','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental templo de estilo gótico tardío del siglo XVI edificado en cantería caliza calavera que exhibe una nave única de colosales proporciones de gran luz espacial cubierta por intrincadas bóvedas de crucería estrellada compleja y la espectacular capilla de la Comunión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03011','ermita','Ermita de la Sangre','Santuario rural del gótico de reconquista primitivo del siglo XIII que presenta muros de piedra con arcos diafragma de medio punto sosteniendo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03055','iglesia','Iglesia Parroquial de los Santos Juanes','Monumental templo del siglo XVIII de estilo barroco academicista erigido en la comarca de la Vega Baja con aparejo de mampostería y ladrillo visto que destaca por su espaciosa nave central cubierta por bóvedas de cañón con lunetos, una gran cúpula sobre el crucero y una espectacular fachada flanqueada por pilastras de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','palacio','Palacio Condal de Cocentaina','Espectacular y majestuoso complejo señorial fortificado del gótico civil','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','monumento','Castillo de Cocentaina','Imponente torre fortaleza de estilo gótico militar del siglo XIV emplazada sobre una escarpada aguja rocosa caliza, de la que subsiste de forma monumental su estructura de planta cuadrada con garitones volados, saeteras defensivas y muros de sillería labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','iglesia','Iglesia Parroquial de Santa María','Fábrica columnaria de transición gótico-renacentista construida en cantería caliza calavera que exhibe una nave única cubierta por bóvedas de crucería estrellada compleja y reformas barrocas con yeserías políscromas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','iglesia','Monasterio de la Virgen del Milagro','Complejo monacal de las clarisas fundado en el siglo XVI con fachadas de mampostería y piedra labrada que encierra un bello claustro porticado y un retablo de gran valor artístico nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','monumento','Núcleos de población de Confrides','El término municipal incluye los siguientes núcleos de población: L''Abdet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','monumento','Castillo de Confrides / El Castellet','Ruinas de una fortaleza militar medieval de origen andalusí dispuesta sobre un peñasco escarpado de la comarca del Valle de Guadalest, de la que restan potentes lienzos de muralla de mampostería basta adaptados a la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco del siglo XVIII levantado con muros de mampostería encintada que aloja un presbiterio cubierto por bóveda de cañón con lunetos y una pequeña torre campanario baja de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03058','monumento','Castillo de Santa Bárbara / Castillo de Cox','Espectacular y suntuosa residencia señorial fortificada de origen andalusí profundamente reconstruida en el siglo XV con muros de sillería caliza regular de primer orden sobre un cerro que destaca por su impecable estado de conservación y salas cubiertas por bóvedas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03058','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental fábrica barroca del siglo XVIII de proporciones herrerianas erigida en cantería caliza y ladrillo que destaca por su espaciosa nave central cubierta por bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03061','iglesia','Iglesia Parroquial de San Miguel','Templo de la Vega Baja edificado mediante el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que aloja una nave única con cubiertas de bóveda de arista modesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03062','iglesia','Iglesia Parroquial de Nuestra Señora de Monserrate','Humilde oratorio rural edificado en mampostería tosca encalada que cuenta con una pequeña fachada sobria coronada por una espadaña de ladrillo visto de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03064','iglesia','Iglesia Parroquial de Nuestra Señora de los Dolores','Templo barroco de mediados del siglo XVIII proyectado bajo las trazas del Cardenal Belluga en la Vega Baja, construido con muros de mampostería encintada y contrafuertes calizos que alberga una nave única cubierta por bóvedas de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','monumento','Núcleos de población de Elche/Elx','El término municipal incluye los siguientes núcleos de población: Torrellano, El Altet, Las Bayas y La Hoya.','inventario_monumentos_pdf');
