INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','palacio','Palacio de Altamira / Alcázar de la Señoría','Espectacular palacio señorial fortificado del gótico civil valenciano del siglo XV edificado en sillería caliza regular sobre una antigua alcazaba musulmana, de la que destaca su majestuosa torre del homenaje de planta cuadrangular almenada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','iglesia','Basílica de Santa María','Magna obra del barroco clasicista valenciano construida entre los siglos XVII y XVIII que exhibe una espectacular fachada-retablo profusamente decorada con columnas salomónicas esculpidas por Nicolás de Bussy y un interior cupulado universal donde se representa anualmente el Misteri d''Elx.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','monumento','Torre de la Calahorra','Recia torre defensiva de origen almohade del siglo XIII construida con gruesos muros de tapial y posterior mampostería cristiana que formaba parte de las murallas de la medina conservando salas abovedadas mudéjares.','inventario_monumentos_pdf');
