INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03017','monumento','Castillo de Elda','Ruinas consolidadas de un imponente palacio señorial fortificado del siglo XV de la familia Coloma erigido en sillería y mampostería sobre un alcázar andalusí en el Valle del Vinalopó, del que destacan sus paños almenados y torres angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03017','iglesia','Iglesia Parroquial de Santa Ana','Templo renacentista del siglo XVI modificado en el siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y una robusta torre campanario de tres cuerpos escalonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03068','iglesia','Iglesia Parroquial de San Cayetano','Humilde oratorio de la comarca del Condado de Cocentaina edificado en mampostería tosca encalada que cuenta con una pequeña espadaña de ladrillo visto de un solo vano y un interior enfoscado en yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03018','monumento','Castillo de Finestrat (Ruinas)','Vestigios medievales de una fortaleza defensiva de origen andalusí emplazada de forma espectacular sobre el cerro que domina el núcleo urbano antiguo del que subsisten paños fragmentados de muralla basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03018','iglesia','Iglesia Parroquial de San Bartolomé','Fábrica barroca del siglo XVIII que presenta una espaciosa nave central','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03070','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo de la Vega Baja edificado en el siglo XVIII mediante el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que aloja una nave única reformada en el barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03071','iglesia','Iglesia Parroquial de San Miguel Arcángel','Fábrica barroca del siglo XVIII levantada con paramentos de mampostería encintada que aloja un presbiterio con bóveda de cañón con lunetos y una torre campanario baja de planta cuadrada con remates de cantería tosca de la Marina Alta.','inventario_monumentos_pdf');
