INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03083','iglesia','Iglesia Parroquial de Santa María','Fábrica del barroco triunfante del siglo XVII erigida en cantería caliza calavera que exhibe una nave única cubierta por bóvedas de cañón con lunetos y ricas yeserías exentas en su presbiterio.','inventario_monumentos_pdf');
