INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04092','monumento','Yacimiento de Tíjola la Vieja','Impresionante conjunto fortificado medieval de origen andalusí emplazado de forma espectacular sobre una escarpada muela rocosa, del que restan de forma monumental imponentes lienzos de muralla de mampostería basta y aljibes subterráneos.','inventario_monumentos_pdf');
