INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04028','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Edificio del siglo XVI de líneas mudéjares construido en la comarca del Levante Almeriense que alberga una nave única con cubiertas de madera de sabina y pino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04094','iglesia','Iglesia Parroquial de Santa María','Humilde templo serrano de los Filabres edificado en mampostería de pizarra rústica encalada que cuenta con una pequeña fachada sobria coronada por una espadaña de ladrillo visto de dos ojos y un interior enfoscado en yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04095','iglesia','Santuario de la Virgen de la Cabeza','Complejo de peregrinación levantado de forma monumental sobre la cumbre del cerro de Monteagud, edificado en mampostería rústica de pizarra y piedra que sirve como hito devocional comarcal.','inventario_monumentos_pdf');
