INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04096','iglesia','Iglesia Parroquial de Santa María','Modesta edificación de culto mudéjar de la Sierra de los Filabres construida en el siglo XVI mediante el tradicional aparejo mixto de mampostería basta y verdugadas de ladrillo visto que aloja una nave única con cubiertas de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04097','monumento','Castillo de Velefique (Ruinas)','Vestigios medievales de una inexpugnable e histórica fortaleza defensiva de origen andalusí de la que subsisten paños fragmentados de murallas de mampostería de pizarra rústica seca adaptados al relieve geológico.','inventario_monumentos_pdf');
