INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04098','monumento','Castillo de los Fajardo','Obra cumbre de la arquitectura del renacimiento militar y señorial universal del siglo XVI edificada por los marqueses de Los Vélez en sillería de la máxima finura técnica sobre una cresta rocosa escarpada, destacando su colosal torre del homenaje, paños almenados y el espacio del célebre patio renacentista esculpido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04098','iglesia','Iglesia de Santiago Apóstol','Joya monumental góticomudéjar de transición del siglo XVI erigida en cantería de','inventario_monumentos_pdf');
