INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04099','iglesia','Iglesia de San José','Monumental fábrica del siglo XVIII de estilo barroco que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y un retablo mayor dorado con ricas yeserías exentas.','inventario_monumentos_pdf');
