INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90426','iglesia','Iglesia Parroquial de la Anunciación','Templo mudéjar rural del Marquesado de Zenete construido en el siglo XVI con muros de mampostería encintada y hiladas de ladrillo visto macizo que aloja una nave única cubierta por una armadura de madera sencilla castellana.','inventario_monumentos_pdf');
