INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18039','iglesia','Iglesia Parroquial de Santa María y San Pedro','Templo del siglo XVI de tradición mudéjar-renacentista con reformas dieciochescas levantado en aparejo tosco de la comarca de Baza que cuenta con una nave única de gran luz espacial techada por una espléndida armadura de madera de par y nudillo bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18039','monumento','El Pósito (Centro de Interpretación)','Antiguo edificio civil del siglo XVIII edificado en mampostería y ladrillo de sillería regular que servía originalmente como almacén comunal de grano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18040','iglesia','Iglesia Parroquial de Santa Ana','Templo de tipología mudéjar rural de la Alpujarra Alta construido en el siglo XVI con muros de mampostería encintada y hiladas de ladrillo visto macizo que aloja una nave única cubierta por una armadura de madera con lacerías moriscas y un campanario integrado de porte defensivo.','inventario_monumentos_pdf');
