INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18044','monumento','Núcleos de población de Cástaras','El término municipal incluye los siguientes núcleos de población: Nieles.','inventario_monumentos_pdf');
