INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18095','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Granada, Letra H (comenzando estrictamente por municipios como Huélago, Huéneja, Huéscar, Huétor de Santillán, Huétor Tájar, Huétor Vega, Íllora, Ítrabo, Iznalloz, etcétera).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18095','monumento','Madrasa Palace','Discover Granada''s Hidden Gem (Full Tour) | Granada Tours 2 ago 2025 — ¡Bienvenidos a una nueva Ruta en Granada! En este video, te','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18097','monumento','Núcleos de población de Huéneja','El término municipal incluye los siguientes núcleos de población: La Huertezuela y Venta del Ratón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18097','monumento','El Castillejo de Huéneja','Ruinas consolidadas de una inexpugnable e histórica fortaleza militar de origen andalusí del siglo XII erigida en tapial y mampostería basta que corona el cerro del Marquesado de Zenete, de la que restan potentes lienzos de muralla y estructuras de aljibes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18097','iglesia','Iglesia Parroquial de la Anunciación','Monumental templo del siglo XVI que fusiona el gótico tardío y el mudéjar construido en cantería y ladrillo visto, destacando su elevado presbiterio cubierto por una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','monumento','Núcleos de población de Huéscar','El término municipal incluye los siguientes núcleos de población: Duda, Fuencaliente y La Sagra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','iglesia','Iglesia de Santa María de la Encarnación (Colegiata de Huéscar)','Magna obra de la arquitectura del renacimiento y transición tardogótica del siglo XVI declarada Monumento Nacional, construida en cantería de primer orden bajo diseño de la escuela de Diego de Siloé, que destaca por sus colosales columnas jónicas estriadas, sus elevadas bóvedas de crucería estrellada compleja y una portada plateresca monumental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','monumento','Torre de la Canastera','Recia torre defensiva y atalaya militar de origen andalusí de planta circular erigida en tapial de cal y mampostería basta en Sierra de la Sagra, la cual conserva de forma monumental sus saeteras de vigilancia territorial en la comarca de Huéscar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','iglesia','Convento de San Francisco','Complejo monástico fundado en el siglo XVII edificado en sillería y ladrillo visto macizo que conserva un claustro barroco de planta cuadrangular porticada y una iglesia conventual de nave única con capillas hornacinas laterales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18099','monumento','Núcleos de población de Huétor de Santillán','El término municipal incluye los siguientes núcleos de población: El Molinillo y Prado Negro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18099','iglesia','Iglesia Parroquial de la Encarnación','Templo mudéjar del siglo XVI edificado con cajones de mampostería y esquinales de sillería caliza calavera de Sierra de Huétor que resguarda una nave única techada por una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','monumento','Núcleos de población de Huétor Tájar','El término municipal incluye los siguientes núcleos de población: Venta Nueva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','monumento','Torre de Huétor / El Torreón','Recia e histórica torre de defensa señorial fortificada de origen andalusí y posterior reforma medieval cristiana de planta cuadrangular erigida en tapial de cal y mampostería basta, la cual constituye el emblema del casco histórico con su fisonomía militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','iglesia','Iglesia Parroquial de Santa Elizabeth (Santa Isabel)','Fábrica barroca del siglo XVIII construida con paramentos de mampostería encintada del Poniente Granadino y hiladas de ladrillo visto macizo que presenta una espaciosa nave central cubierta por bóveda de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18101','iglesia','Iglesia Parroquial de la Encarnación','Edificio de culto del siglo XVI de tradición mudéjar levantado con cajones de mampostería ordinaria y esquinales de sillería caliza que cuenta con una pequeña torre campanario de dos cuerpos y un artesonado de madera modesto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','monumento','Núcleos de población de Íllora','El término municipal incluye los siguientes núcleos de población: Alomartes, Tocón, Escóznar, Obeilar y Brácana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','monumento','Castillo de Íllora (El Ojo Derecho de Granada)','Espectacular y colosal complejo fortificado medieval de origen andalusí del siglo XIV erigido en sillería de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','iglesia','Iglesia Parroquial de la Encarnación','Magna obra que constituye un bellísimo ejemplo de la arquitectura renacentista y del gótico tardío del siglo XVI construida en cantería caliza calavera de primer orden bajo trazas de Diego de Siloé, destacando sus colosales naves de gran luz espacial y una espectacular portada monumental plateresca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','monumento','Molino de la Torre (Alomartes)','Espectacular e histórico complejo industrial hidráulico tradicional de molienda del siglo XVIII edificado en mampostería y piedra labrada que conserva sus cárcavos de cantería y su maquinaria original alimentada por el manantial local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18103','iglesia','Iglesia Parroquial de Nuestra Señora del Carmen','Templo de la comarca de la Costa edificado en el siglo XVIII de líneas barroco-clasicistas mediante el tradicional aparejo mixto de mampostería basta y verdugadas de ladrillo visto que aloja una nave única con cubiertas de bóveda de arista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','monumento','Núcleos de población de Iznalloz','El término municipal incluye los siguientes núcleos de población: Domingo Pérez.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','iglesia','Iglesia Parroquial de Nuestra Señora de los Remedios','Joya monumental de la arquitectura renacentista y mudéjar del siglo XVI declarada Monumento Nacional, construida en cantería caliza calavera de primer orden bajo diseño de Diego de Siloé,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','monumento','Castillo de los Moros / Castillo de Iznalloz (Ruinas)','Vestigios medievales de una inexpugnable e histórica fortaleza defensiva de origen andalusí emplazada sobre un promontorio de la que subsisten paños fragmentados de muralla basta adaptados al relieve de la comarca de Los Montes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','monumento','Puente Romano sobre el río Cubillas','Estructura de ingeniería civil tradicional de sillería de piedra que salva el cauce del río mediante un robusto arco de medio punto ejecutado con dovelas de gran solidez estructural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18107','iglesia','Iglesia Parroquial de la Santa Cruz','Fábrica del siglo XVIII de estilo barroco rural de la comarca de Alhama levantada con muros de mampostería encintada que aloja un presbiterio cubierto por bóveda de cañón con lunetos y un interior con techumbre de madera castellana modesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18108','monumento','El Torreón / Torre de Jerez','Recia atalaya defensiva de origen andalusí del siglo XII de planta cuadrada erigida en tapial y mampostería basta en el Marquesado de Zenete, la cual conserva de forma monumental sus plantas abovedadas y saeteras de vigilancia perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18108','iglesia','Iglesia Parroquial de la Anunciación','Templo del siglo XVI de tradición mudéjar-renacentista levantado con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18109','iglesia','Iglesia Parroquial de San Antonio de Padua','Humilde oratorio costero edificado en mampostería tosca encalada que cuenta con una pequeña fachada sobria coronada por una espadaña de ladrillo visto de un solo vano y un interior techado por una armadura de madera sencilla castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18111','monumento','Alfares Tradicionales de Jun','Espacio de trascendencia industrial urbana de la Vega de Granada constituido por los históricos alfares, hornos de mampostería y cuevas destinados a la fabricación artesanal de cerámica tradicional de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18111','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Fábrica de tradición mudéjar levantada con el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que resguarda una nave única techada por una estructura de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18112','monumento','El Fuerte de Juviles','Ruinas espectaculares de una colosal e inexpugnable fortaleza defensiva militar de origen andalusí (siglo X al XII) que corona la cima de un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18112','iglesia','Iglesia Parroquial de Santa María de la Mayor','Templo mudéjar del siglo XVI construido con paramentos de mampostería encintada de pizarra que aloja una nave única techada por una armadura de madera de par y nudillo bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18115','monumento','Núcleos de población de Láchar','El término municipal incluye los siguientes núcleos de población: Peñuelas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18115','palacio','Castillo de Láchar / Palacio de Láchar','Espectacular residencia señorial fortificada del siglo XIX de estilo historicista y neomudéjar construida sobre las ruinas de una antigua atalaya andalusí en la Vega de Granada, que destaca por sus fachadas almenadas, torres angulares y estancias decoradas con yeserías de filigrana morisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18115','iglesia','Iglesia Parroquial de la Virgen del Rosario','Edificio de culto de líneas clasicistas levantado con cajones de mampostería ordinaria y esquinales de sillería caliza que presenta una fachada sobria con una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','monumento','Castillo de Lanjarón (El Castillo de los Moros)','Ruinas espectaculares de una inexpugnable e histórica fortaleza militar de origen andalusí y posterior señorío cristiano emplazada de forma monumental sobre un escarpado peñasco rocoso calizo que domina la entrada a la Alpujarra, de la que restan potentes lienzos almenados de mampostería basta y la base de su gran torre del homenaje de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','iglesia','Iglesia Parroquial de la Encarnación','Fábrica góticomudéjar del siglo XVI de nave única levantada en aparejo de cantería caliza calavera y mampostería que alberga un presbiterio cubierto por bóvedas de crucería estrellada gótico tardías y un retablo mayor dorado barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18117','monumento','Castillo del Barrio / Los Castillejos','Vestigios fortificados medievales de dos fortalezas defensivas de origen andalusí situados de forma espectacular en el Marquesado de Zenete, construidos en tapial y mampostería gruesa adaptados al relieve geológico de la montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18117','iglesia','Iglesia Parroquial de la Anunciación','Templo del siglo XVI de líneas mudéjares que presenta una espaciosa nave central techada por una colosal armadura mudéjar de madera de par y nudillo policromada y una robusta torre campanario de planta cuadrada baja con remates de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18119','monumento','Núcleos de población de Lecrín','El término municipal incluye los siguientes núcleos de población: Talará, Mondújar, Murchas, Acequias, Béznar y Chite.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18119','monumento','Castillo de Mondújar','Ruinas espectaculares de una importante fortaleza militar de origen andalusí del siglo XV construida por orden nazarí mediante potentes muros de tapial de cal y mampostería basta, de la que subsisten paños de muralla adaptados al relieve del Valle de Lecrín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18119','iglesia','Iglesia Parroquial de la Inmaculada Concepción (Murchas)','Templo mudéjar del siglo XVI levantado con aparejo de mampostería y sillería caliza calavera en sus','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18121','monumento','Núcleos de población de Lobras','El término municipal incluye los siguientes núcleos de población: Tímar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18121','iglesia','Iglesia Parroquial of Nuestra Señora del Rosario','Templo de tipología mudéjar rural de la Alpujarra Baja construido en el siglo XVI con muros de mampostería encintada de pizarra y hiladas de ladrillo visto macizo que presenta una espadaña de dos ojos y un interior techado por una armadura de madera sencilla castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','monumento','Núcleos de población de Loja','El término municipal incluye los siguientes núcleos de población: Ventorros de San José, Venta del Rayo y Cuesta de la Palma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','monumento','Alcazaba de Loja y Aljibe Monumental','Inmenso e histórico complejo fortificado militar de origen andalusí del siglo IX profundamente reedificado tras la reconquista en sillería y mampostería basta que corona el cerro de la ciudad en el Poniente Granadino, del que sobresalen la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','iglesia','Iglesia Mayor de la Encarnación','Magna fábrica que fusiona el gótico final y el renacimiento construida en cantería caliza calavera de primer orden entre los siglos XV y XVI, destacando su espectacular y colosal presbiterio poligonal cubierto por intrincadas bóvedas de crucería estrellada y su gran portada clasicista diseñada por Diego de Siloé.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','iglesia','Iglesia de San Gabriel','Joya monumental del renacimiento español declarada Monumento Nacional, construida en sillería de cantería de primer orden que exhibe una nave única de colosales proporciones de gran luz espacial cubierta por espectaculares bóvedas de cañón casetonadas de valor universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','palacio','Palacio de Narváez (Ayuntamiento)','Edificio civil barroco del siglo XVIII de arquitectura señorial de la familia del General Narváez que presenta una fachada palaciega con portalón de cantería dovelado, grandes blasones heráldicos labrados en piedra caliza, balconajes de forja artística y un patio porticado central jónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18123','iglesia','Iglesia Parroquial de San Antonio de Padua','Humilde templo de la comarca de Guadix edificado en mampostería de pizarra rústica encalada en las faldas de Sierra Nevada que cuenta con una pequeña fachada sobria coronada por una espadaña de ladrillo visto de un solo vano y un interior techado por una armadura de madera castellana modesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18124','monumento','Núcleos de población de Lújar','El término municipal incluye los siguientes núcleos de población: Los Gualchos -si aplica-.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18124','iglesia','Iglesia Parroquial del Santo Cristo de la Cabrilla','Fábrica mudéjar del siglo XVI levantada en la Sierra de Lújar con recios muros de piedra y ladrillo visto de la comarca de la Costa que aloja una nave única techada por una estructura de madera castellana modesta de par y nudillo y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18124','monumento','Provincia de Granada','Sub-bloques de las letras H, I, J y L completados de forma íntegramente correlativa hasta el municipio de Lújar inclusive.','inventario_monumentos_pdf');
