INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19028','monumento','Puente de la Tableta','Estructura hidráulica tradicional de un solo ojo de medio punto ejecutada en mampostería basta y lajas de pizarra rústica que se conserva como el hito caminero antiguo de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18911','monumento','Núcleos de población de Vegas del Genil','El término municipal incluye los siguientes núcleos de población: Purchil, Ambroz y Belicena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18911','iglesia','Iglesia Parroquial de San Miguel Arcángel (Purchil)','Fábrica del siglo XVI de líneas mudéjares con importantes reformas barrocas posteriores de la Vega de Granada, construida con muros de mampostería y verdugadas de ladrillo visto macizo que aloja un presbiterio abovedado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18184','monumento','Castillo de los Ulloa / Torre de Vélez de Benaudalla','Recia torre defensiva y atalaya militar de origen andalusí de planta hexagonal erigida en sillería caliza regular y mampostería basta en el núcleo del casco histórico que servía como puesto avanzado de control territorial y se encuentra integrada de forma monumental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18184','monumento','Jardín Nazarí / Jardín de los Sentidos','Joya monumental de la arquitectura paisajística e hidráulica andalusí del siglo XV que conserva de forma monumental huertos escalonados, acequias, fuentes y una intrincada red de conducciones hidráulicas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18185','monumento','Núcleos de población de Ventas de Huelma','El término municipal incluye los siguientes núcleos de población: Ácula.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18185','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Modesta edificación de culto de la comarca de Alhama levantada con cajones de mampostería ordinaria y verdugadas de ladrillo visto macizo que presenta una fachada neoclásica sobria rematada por una pequeña espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18908','monumento','Núcleos de población de Villamena','El término municipal incluye los siguientes núcleos de población: Cozvíjar y Cónchar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18908','iglesia','Iglesia Parroquial de San Juan Bautista (Cozvíjar)','Templo mudéjar del siglo XVI edificado mediante el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto que aloja una nave única con cubiertas de madera de par y nudillo con lacerías moriscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','palacio','Palacio de el Cuzco','Espectacular palacio señorial del barroco clasicista del siglo XVIII edificado en sillería de piedra regular caliza calavera y mampostería basta por orden del arzobispo de Granada, el cual presenta una fachada monumental de suntuosa decoración arquitectónica de líneas herrerianas flanqueada por dos torreones angulares y un patio central porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','iglesia','Iglesia Parroquial de Nuestra Señora del Pilar','Monumental fábrica de tradición mudéjar-renacentista levantada en aparejo de piedra y ladrillo visto de la comarca de la Vega de Granada que cuenta con una nave única techada por una estructura de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18192','monumento','Núcleos de población de Zafarraya','El término municipal incluye los siguientes núcleos de población: El Almendral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18192','iglesia','Iglesia Parroquial de la Purísima Concepción','Fábrica de líneas neoclásicas del siglo XVIII levantada con cajones de mampostería de la comarca de Alhama que resguarda una nave de gran amplitud espacial y una robusta torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18913','monumento','Castillo de Zagra','Ruinas espectaculares de una importante fortaleza militar de origen andalusí de los siglos XII y XIII de la que subsisten de forma monumental paños de muralla fortificados de tapial, cubos defensivos y una recia torre del homenaje adaptada al Poniente Granadino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','iglesia','Iglesia Parroquial de la Anunciación','Monumental fábrica del siglo XVI de tradición mudéjar levantada con aparejo de mampostería y sillería caliza calavera en sus esquinales de la comarca de Baza, que alberga una nave única techada por una colosal armadura mudéjar de madera de par y nudillo policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','monumento','Provincia de Granada','Completada al 100% (174 municipios, cerrado estrictamente tras Zújar conforme a su nomenclátor oficial).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','monumento','Próxima provincia sugerida para la Hoja de Ruta','Provincia de Málaga (avanzando en el bloque de Andalucía de forma natural por el arco bético meridional y costero).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Málaga, Letra A (comenzando estrictamente por municipios como Alameda, Alcaucín, Alfarnate, Alfarnatejo, Algarrobo, Algatocín, Alhaurín de la Torre, Alhaurín el Grande, Almáchar, Almargen, Almogía, Álora, Alozaina, Alpandeire, Antequera, Árchez, Archidona, Ardales, Arenas, Arriate, Atajate, Benadalid, Benahavís, Benalauría, Benalmádena, Benamargosa, Benamocarra, Benaoján, Benarrabá, etcétera).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90433','monumento','Castillo de Zalia','Ruinas espectaculares de una inexpugnable e histórica fortaleza militar de origen andalusí y posterior señorío cristiano emplazada sobre una escarpada meseta rocosa de la Axarquía, de la que restan potentes lienzos almenados de mampostería gruesa y torres angulares circulares adaptadas a la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90433','iglesia','Iglesia Parroquial de Nuestra Señora del Rosario','Fábrica del siglo XVI de líneas mudéjares reformada en el siglo XVIII con paramentos de mampostería encintada que alberga una nave techada por una estructura de madera castellana de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','monumento','Venta de Alfarnate','Espectacular y excelso edificio civil de arquitectura popular del siglo XVII que constituye una de las ventas de carretera más antiguas de Andalucía, construida con gruesos muros portantes de mampostería encalada, vigas de madera de sabina y teja moruna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','iglesia','Iglesia Parroquial de Santa Ana','Templo mudéjar del siglo XVI edificado mediante el tradicional aparejo mixto de mampostería y verdugadas de ladrillo visto que destaca por su robusta torre campanario de tres cuerpos escalonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90435','iglesia','Iglesia Parroquial del Santo Cristo de la Cabrilla','Modesta edificación de culto de montaña en los Pirineos de la Axarquía levantada en el siglo XVIII con cajones de mampostería ordinaria y esquinales de sillería que cuenta con una pequeña torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','monumento','Necrópolis Fenicia de Trayamar','Complejo arqueológico del siglo VII a.C. de relevancia universal que conserva de forma monumental tumbas de cámara construidas con grandes bloques de sillería de piedra regular arenisca que documentan la colonización fenicia en el litoral paleomediterráneo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','monumento','Torre Ladeada y Torre Derecha (Torre Nueva)','Pareja monumental de torres vigía costeras de origen andalusí y renacentista erigidas en sillería regular y mampostería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','iglesia','Iglesia Parroquial de Santa Ana','Fábrica mudéjar del siglo XVI levantada con recios muros de piedra y ladrillo visto que alberga una nave única techada por una espléndida armadura de madera con tirantes decorados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90437','iglesia','Iglesia Parroquial de Nuestra Señora del Rosario','Templo barroco del siglo XVIII levantado en la Serranía de Ronda con muros de mampostería encintada que aloja un presbiterio cubierto por una gran cúpula sobre pechinas coronada con una linterna decorada con cerámica vidriada azul y una torre con capitel ochavado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90438','iglesia','Iglesia Parroquial de San Sebastián','Fábrica neoclásica del siglo XIX erigida en cantería caliza y ladrillo tras un terremoto, que presenta una espaciosa planta de cruz latina sostenida por robustos pilares toscanos y una sobria fachada simétrica con una torre campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','monumento','Arco de Cozvíjar','Monumental hito y portalón-puerta de acceso fortificado de origen andalusí del siglo XII perteneciente a las antiguas murallas de la medina,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','iglesia','Iglesia Parroquial of Nuestra Señora de la Encarnación','Fábrica gótico-mudéjar del siglo XVI edificada con contrafuertes de cantería caliza calavera y ladrillo que destaca por su presbiterio cubierto con bóvedas de crucería gótico tardías de gran luz espacial y una esbelta torre campanario exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90440','iglesia','Iglesia Parroquial de San Mateo','Edificio de culto mudéjar del siglo XVI levantado en la Axarquía con el tradicional aparejo de cajones de mampostería y hiladas de ladrillo visto macizo que resguarda una nave única techada por una estructura de madera castellana modesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90441','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVI de tradición mudéjar-renacentista con importantes reformas barrocas del siglo XVIII levantado en aparejo de piedra y ladrillo visto que cuenta con una nave única de gran luz espacial techada por una espléndida armadura de madera con lacerías moriscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90442','monumento','Castillo de Almogía / Torre de la Vela','Ruinas de una fortaleza militar medieval de origen andalusí de planta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90442','iglesia','Iglesia Parroquial de nuestra Señora de la Asunción','Templo del siglo XVI levantado con recios muros de piedra y ladrillo visto que destaca por su espaciosa nave central techada por una espléndida armadura de madera de par y nudillo con tirantes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32001','monumento','Torreón de María Sagredo y Murallas','Vestigios del recinto fortificado medieval de origen andalusí consistentes en un potente cubón defensivo de planta cilíndrica y paños almenados de mampostería basta integrados de forma monumental en un parque periurbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32001','iglesia','Iglesia Parroquial de Santa Ana','Fábrica barroca del siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y un campanario de planta cuadrada baja con remates de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90443','catedral','Iglesia Parroquial de San Antonio de Padua (Catedral de la Serranía)','Monumental templo del siglo XVIII de estilo barroco academicista neoclásico erigido en cantería caliza de la Serranía de Ronda que destaca por su espaciosa nave central de proporciones catedralicias, una espectacular fachada flanqueada por sus dos robustas torres campanario gemelas de planta cuadrada con remates de piedra y una gran cripta subterránea abovedada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Núcleos de población de Antequera','El término municipal incluye los siguientes núcleos de población: Bobadilla, Cartaojal y Villanueva de Cauche.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Sitio de los Dólmenes de Antequera (Menga, Viera y El Romeral)','Magna obra cumbre del megalitismo universal declarada Patrimonio de la Humanidad por la UNESCO, constituida por tres colosales sepulcros de cámara y corredor erigidos con gigantescos bloques de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','iglesia','Real Colegiata de Santa María la Mayor','Joya monumental del renacimiento español declarada Monumento Nacional, construida en sillería de cantería caliza de primer orden por la escuela de Siloé en el siglo XVI, que exhibe una fachada monumental que emula un arco de triunfo clasicista flanqueada por pilastras y un interior columnario cubierto por un colosal alfarje de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Alcazaba de Antequera y Torre del Papabellotas','Inmenso e histórico complejo fortificado militar de origen andalusí profundamente reconstruido en el siglo XIV que destaca por sus potentes murallas almenadas con torres albarranas y una descomunal torre del homenaje de planta cuadrada coronada por un templete barroco de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Arco de los Gigantes','Monumental estructura civil y humanista del siglo XVI ejecutada en sillería regular caliza calavera que exhibe una gran portada de medio punto concebida originalmente como un museo exento al aire libre para integrar inscripciones epigráficas latinas y relieves romanos de la antigua Singilia Barba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','iglesia','Iglesia del Carmen','Espectacular fábrica del barroco triunfante del siglo XVII erigida en cantería que destaca por su espaciosa nave única de gran luz espacial techada por un colosal artesonado mudéjar de madera policromada y un fastuoso retablo mayor dorado churrigueresco considerado una de las obras cumbres de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Provincia de Málaga','Sub-bloque de la letra A completado íntegramente de forma correlativa hasta el municipio de Antequera inclusive.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Último sub-bloque procesado','Letra A (completado hasta el municipio de Antequera, inclusive).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Málaga, Letra B (comenzando estrictamente por municipios como Árchez, Archidona, Ardales, Arenas, Arriate, Atajate, Benadalid, Benahavís, Benalauría, Benalmádena, Benamargosa, Benamocarra, Benaoján, Benarrabá, etcétera).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','monumento','Plaza Ochavada','Obra cumbre de la arquitectura civil y del urbanismo barroco andaluz del siglo XVIII construida por Francisco Frías y Antonio González, la cual exhibe una insólita planta octogonal perfecta perimetrada por fachadas unificadas de ladrillo visto policromo y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','ermita','Castillo-Mezquita de Archidona (Ermita de la Virgen de Gracia)','Espectacular y colosal complejo fortificado medieval de origen andalusí del siglo IX que corona la silueta de la montaña en sillería y tapial, el cual conserva de forma monumental las estructuras completas de la antigua mezquita islámica con sus arcos de herradura adaptados a la iglesia-santuario posterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','iglesia','Convento de Santo Domingo','Complejo monacal del siglo XVI fundado por los condes de Ureña que presenta una fachada monumental de cantería y un patio central porticado con columnas toscanas de piedra labrada caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','iglesia','Iglesia de Santa Ana','Monumental fábrica de transición tardogótica y renacentista del siglo XVI erigida en cantería que destaca por su presbiterio cubierto con bóvedas de crucería estrellada compleja y una esbelta torre campanario con capitel de cerámica vidriada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','monumento','Castillo de la Peña de Ardales','Espectacular e inexpugnable complejo fortificado de origen andalusí del siglo IX emplazado de forma espectacular sobre la cresta de una vertiginosa muela rocosa escarpada que domina la comarca, construido en sillería caliza y mampostería basta del que destacan la torre del homenaje y lienzos almenados enteros adaptados a la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','monumento','Cueva de Ardales (Cueva de la Doña)','Cavidad natural caliza de relevancia universal protegida por la UNESCO que conserva magníficas muestras de arte rupestre paleolítico con representaciones zoomorfas y signos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','iglesia','Iglesia Parroquial de Nuestra Señora de los Remedios','Templo del siglo XVI de tradición mudéjarrenacentista levantado en aparejo mixto de piedra y ladrillo visto que cuenta con una nave única de gran luz espacial techada por una espléndida armadura de madera con lacerías moriscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','monumento','Núcleos de población de Arenas','El término municipal incluye los siguientes núcleos de población: Daimalos y El Burgo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','monumento','Castillo de Bentomiz','Ruinas espectaculares de una colosal e inexpugnable fortaleza militar de origen andalusí de los siglos X y XI que corona la cima de un cerro escarpado en la Axarquía, de la que subsisten paños fragmentados de murallas de tapial y grandes aljibes subterráneos de mampostería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','iglesia','Alminar de Daimalos (Torre de la Iglesia)','Recia atalaya defensiva y campanario de tradición mudéjarislámica del siglo XIII construida enteramente en ladrillo visto de planta cuadrada que constituye un hito de la arquitectura mudéjar rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','iglesia','Iglesia Parroquial de Santa Catalina','Fábrica mudéjar del siglo XVI levantada con recios muros de piedra y ladrillo que alberga una techumbre interior de madera de par y nudillo bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90444','iglesia','Iglesia Parroquial de San Juan Letrán','Edificio de culto de la comarca de la Serranía de Ronda levantado con cajones de mampostería ordinaria y verdugadas de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29021','iglesia','Iglesia Parroquial de San Roque','Modesta construcción de culto de la Serranía de Ronda levantada en el siglo XVIII con muros de mampostería encintada y esquinales de sillería de montaña caliza que cuenta con una pequeña fachada neoclásica sobria rematada por un frontón triangular y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29022','monumento','Castillo de Benadalid','Espectacular fortaleza militar medieval de origen andalusí del siglo XIII erigida en sillería de piedra regular y mampostería basta de planta circular, la cual se conserva de forma monumental albergando en su patio de armas central el histórico cementerio de la villa, flanqueada por recios cubos defensivos cilíndricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29022','iglesia','Iglesia Parroquial de San Isidoro','Fábrica del siglo XVI de líneas mudéjares con reformas barrocas del siglo XVIII construida en aparejo de piedra de la Serranía de Ronda que alberga una nave única techada por una armadura de madera castellana modesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','monumento','Castillo de Montemayor','Ruinas espectaculares de una inexpugnable e histórica fortaleza militar de origen andalusí del siglo X emplazada de forma espectacular sobre una elevada estribación de la Serranía de Ronda dominando la Costa del Sol, del que restan potentes lienzos almenados de mampostería basta, torres de flanqueo cuadrangulares y la base de su torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','monumento','Torre de la Leonera y Torres Vigía','Sistema defensivo y de vigilancia tradicional costera y de montaña constituido por una serie de atalayas de planta cilíndrica y cuadrada construidas en sillería y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29024','iglesia','Iglesia Parroquial of Santo Domingo de Guzmán','Fábrica de tradición barroco-clasicista levantada en el siglo XVIII con cajones de mampostería de montaña de la Serranía de Ronda y esquinales de piedra labrada que aloja un presbiterio con bóveda de cañón con lunetos y una torre campanario baja de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29024','monumento','Columbacio Romano (Ruinas)','Vestigios arqueológicos de una estructura funeraria familiar de época romana imperial construida en sillarejo de piedra seca en el entorno periurbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','monumento','Núcleos de población de Benalmádena','El término municipal incluye los siguientes núcleos de población: Benalmádena Pueblo, Arroyo de la Miel y Benalmádena Costa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','monumento','Castillo de Colomares','Monumental e insólito complejo arquitectónico civil de estilo historicista y neomudéjar construido a finales del siglo XX a base de ladrillo visto, piedra tallada y cemento que emula de forma','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','monumento','Torre Bermeja y Torre Muelle','Espectacular pareja de torres vigía costeras del siglo XVI erigidas en sillería regular y mampostería basta sobre el litoral de la Costa del Sol destinadas históricamente al control de las incursiones piratas berberiscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','iglesia','Iglesia Parroquial de Santo Domingo de Guzmán (Pueblo)','Edificio de culto de líneas barroco-clasicistas levantado con paramentos encalados simétricos que presenta una robusta torre campanario de planta cuadrada con remates de piedra tosca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29026','iglesia','Iglesia Parroquial de la Encarnación','Fábrica de tradición mudéjar del siglo XVI levantada en la Axarquía con el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que resguarda una nave única cubierta por bóvedas de cañón con lunetos y una pequeña torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29027','iglesia','Iglesia Parroquial de Santa Ana','Gran edificio del siglo XVI de líneas mudéjares con importantes reformas barrocas posteriores de la Axarquía, construida con muros de mampostería y verdugadas de ladrillo visto macizo que destaca por su espaciosa nave central techada por una espléndida armadura de madera de par y nudillo con tirantes tallados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','monumento','Cueva de la Pileta','Extraordinario santuario arqueológico y rupestre prehistórico de relevancia universal protegido por la UNESCO, constituido por una intrincada red de galerías calizas subterráneas que conserva magníficas muestras de arte rupestre paleolítico con representaciones de peces, caballos y signos abstractos grabados directamente sobre la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','iglesia','Iglesia Parroquial of Nuestra Señora del Rosario','Fábrica gótico-mudéjar de transición del siglo XVI levantada con recios muros de piedra de la Serranía de Ronda que alberga una nave única techada por una armadura de madera de par y nudillo bien conservada con tirantes decorados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29029','iglesia','Iglesia Parroquial de Nuestra Señora del Rosario','Templo barroco del siglo XVIII levantado con recios muros de mampostería encintada de la Serranía de Ronda que alberga una nave única con crucero rematado por una esbelta cúpula sobre pechinas decorada con azulejería vidriada de gran plasticidad y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29029','monumento','Provincia de Málaga','Sub-bloque inicial de la letra B completado íntegramente de forma correlativa hasta el municipio de Benarrabá inclusive.','inventario_monumentos_pdf');
