INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29043','iglesia','Iglesia Parroquial de la Asunción','Fábrica barroca del siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y una robusta torre campanario de planta cuadrada baja con remates de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29044','monumento','Castillo de Comares / Baluarte de la Tahona','Ruinas espectaculares de una inexpugnable e histórica fortaleza militar de origen andalusí del siglo X emplazada de forma monumental sobre la cresta de una vertiginosa muela rocosa caliza escarpada que domina la Axarquía, del que restan potentes lienzos almenados de mampostería basta y las torres de flanqueo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29044','iglesia','Iglesia Parroquial de Nuestra Señora de la Encarnación','Fábrica gótico-mudéjar de transición del siglo XVI construida en cantería de primer orden que exhibe una colosal nave única de gran luz espacial con portadas renacentistas esculpidas, destacando un artesonado mudéjar de madera policromada con lacerías geométricas de valor universal.','inventario_monumentos_pdf');
