INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','monumento','Plaza de Toros de Cortes de la Frontera','Monumental edificación civil taurina del siglo XIX construida a base de sillería de piedra regular de montaña y mampostería basta que destaca por sus arquerías y se erige como una de las plazas históricas de la comarca.','inventario_monumentos_pdf');
