INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','iglesia','Iglesia de Santa María de la Magdalena','Monumental edificio gótico-renacentista del siglo XVI edificado enteramente en sillería berroqueña que impresiona por sus portadas ricamente labradas de estilo Manuelino portugués y un interior cupulado de amplias proporciones espaciales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','iglesia','Iglesia de San Pedro Apóstol','Templo medieval del siglo XIV construido en mampostería con arcos de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','iglesia','Iglesia de de Nuestra Señora de la Purificación','Templo herreriano de gran envergadura iniciado en el siglo XVI sobre trazas góticas que ostenta una soberbia torre-campanario barroca profusamente decorada en piedra caliza calavera y un interior con grandiosas bóvedas estrelladas y pinturas murales de principios del siglo XX.','inventario_monumentos_pdf');
