INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90479','monumento','Núcleos de población de Benquerencia de la Serena','El término municipal incluye los siguientes núcleos de población: Helechal.','inventario_monumentos_pdf');
