INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90480','iglesia','Iglesia de Nuestra Señora de la Concepción','Inmueble parroquial de filiación renacentista castellana construido en el siglo XVI mediante cajones de mampostería y verdugadas de ladrillo que alberga un coro alto sobre viguetas de madera labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90481','iglesia','Iglesia de Nuestra Señora de los Ángeles','Templo mudéjar tardío del siglo XVI edificado con muros de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90482','iglesia','Iglesia de San Blas','Construcción gótico-renacentista del siglo XVI ejecutada con cantería de granito berroqueño en sus esquinas y contrafuertes que exhibe una fachada sobria con arco de medio punto y una torre campanario rematada en flameros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90483','monumento','Castillo de Burguillos del Cerro','Espectacular fortaleza de primer orden construida por la Orden del Temple en el siglo XIII sobre una alcazaba musulmana que destaca por su imponente torre del homenaje de sillería granítica calavera con saeteras y almenas perfectamente conservadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90483','iglesia','Iglesia de Santa María de la Encina','Templo gótico del siglo XIV convertido en centro de interpretación que presenta tres naves separadas por arcos apuntados sobre pilares cruciformes y una cabecera cubierta con bóveda de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90483','ermita','Ermita de del Cristo de la Humillación','Joya de la arquitectura mudéjar tardomedieval construida en ladrillo y mampostería encalada que cuenta con un porche delantero porticado y un interior decorado con arcos de herradura apuntados.','inventario_monumentos_pdf');
