INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06025','iglesia','Iglesia de la Purísima Concepción','Templo renacentista común del siglo XVI edificado en mampostería local y ladrillo que cuenta con una nave única cubierta por bóveda de cañón con lunetos y una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06026','iglesia','Monasterio de Tentudía','Monasterio matriz fortificado erigido por la Orden de Santiago en el siglo XIII a más de mil metros de altitud que alberga un bellísimo claustro mudéjar de ladrillo visto y un retablo mayor de azulejos gótico-renacentistas ejecutado por Niculoso Pisano en 1518.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06026','monumento','Conventual Santiaguista','Edificio gótico-renacentista del siglo XVI construido en sillería de granito berroqueño que destaca por su claustro de doble piso con arcos de medio punto y una monumental fachada con balconadas clasicistas.','inventario_monumentos_pdf');
