INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06028','iglesia','Iglesia de de Nuestra Señora de la Asunción','Edificio de gran envergadura del siglo XVI levantado en mampostería granítica que presenta una fachada renacentista de severas líneas herrerianas y una potente torre del reloj adosada al presbiterio.','inventario_monumentos_pdf');
