INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06048','monumento','Castillo de Lares','Fortaleza defensiva del siglo XIV emplazada sobre una escarpada cresta de cuarcita que domina el embalse de La Serena, de la que subsiste la espectacular torre del homenaje cilíndrica erigida en sillería rústica por la Orden de Alcántara.','inventario_monumentos_pdf');
