INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37014','iglesia','Iglesia Parroquial de San Salvador','Monumental templo gótico-renacentista del siglo XVI iniciado sobre trazas medievales que destaca por su imponente torrefachada fortificada de sillería granítica y un espacioso interior de gran altura cubierto por una gran armadura de madera restaurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37014','ermita','Ermita de la Santa','Construcción barroca del siglo XVIII con muros de mampostería y sillería en las esquinas que presenta una fachada sobria con hornacina y un atrio exterior porticado sobre columnas graníticas de orden toscano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37016','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI con importantes modificaciones barrocas edificado en las orillas del río Tormes con muros de mampostería y ladrillo visto mudéjar que conserva un presbiterio cupulado sobre pechinas barrocas.','inventario_monumentos_pdf');
