INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37018','iglesia','Iglesia Parroquial de la Asunción','Templo rural ordinario del siglo XVI levantado con sillarejos de granito y mampostería de pizarra que presenta un ábside poligonal reforzado con contrafuertes exteriores y una portada de líneas sencillas.','inventario_monumentos_pdf');
