INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37020','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo catalogado de gran envergadura iniciado en el siglo XVI que combina una monumental cabecera gótica de sillería con una fastuosa techumbre mudéjar de madera labrada del siglo XV en la nave central y un monumental retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37021','iglesia','Iglesia Parroquial de la Asunción','Edificación góticomudéjar tardía del siglo XVI levantada en mampostería vista combinada con ladrillo que alberga un presbiterio cubierto por bóveda de crucería gótica sencilla y una espadaña de dos cuerpos. [1]','inventario_monumentos_pdf');
