INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37072','iglesia','Iglesia Parroquial de de Santo Domingo de Guzmán','Templo del siglo XVI levantado en mampostería granítica y cantería que destaca por su recia torre campanario de tres cuerpos decrecientes y una portada de líneas clasicistas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37071','monumento','Tramo de de la Vía de de la Plata','Calzada romana de primer orden perfectamente conservada que atraviesa el término municipal, ejecutada mediante grandes losas de granito berroqueño asentadas sobre un firme compacto de piedra rústica que servía de eje articulador del oeste peninsular.','inventario_monumentos_pdf');
