INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','monumento','Casco Histórico y Arquitectura Popular','Conjunto histórico-artístico protegido de trazado medieval que conserva en impecable estado sus singulares casas solariegas de entramado de madera, muros gruesos de granito berroqueño, mampostería vista, las tradicionales "batideras" de madera en los portales y las "regaderas" de cantería empotradas en las empinadas calles empedradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','iglesia','Iglesia Parroquial de de Nuestra Señora de la Asunción','Monumental templo del siglo XVI que fusiona elementos góticos con una fastuosa armadura mudéjar de madera labrada con lacerías moriscas en su nave central y un monumental retablo mayor barroco de profusa decoración churrigueresca.','inventario_monumentos_pdf');
