INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37080','iglesia','Iglesia Parroquial de San Juan','Inmueble parroquial ordinario del siglo XVI edificado con muros de mampostería granítica vista y pizarra rústica en la vertiente serrana que alberga una nave única rematada por un coro alto con balaustrada de madera labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37081','iglesia','Iglesia Parroquial de Santa María del Castillo','Monumental fábrica de traza románico-mudéjar iniciada en el siglo XIII y ampliada en el siglo XVI en sillería caliza y ladrillo que destaca por su esbelto ábside semicircular decorado con arquerías ciegas dobles superpuestas y una recia torre campanario que domina la llanura salmantina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37081','monumento','Torreón del de la Villa (La Torreta)','Resto fortificado de la antigua muralla medieval medieval del siglo XIV levantado en mampostería compacta y sillería caliza calavera que servía de vigía estratégico frente a la frontera leonesa.','inventario_monumentos_pdf');
