INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90494','monumento','Torreón de Albolote','Atalaya defensiva de época nazarí del siglo XIV emplazada sobre una elevación estratégica que conserva su estructura cilíndrica de mampostería basta y mortero calcáreo en buen estado de consolidación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90495','iglesia','Iglesia Parroquial de la Anunciación','Templo renacentista castellano común del siglo XVI levantado con sillarejos de piedra rústica y mampostería vista que presenta una portada clasicista moldurada y una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90496','iglesia','Iglesia Parroquial de del Santo Cristo de la Salud','Edificación mudéjar de la Alpujarra construida en el siglo XVI con muros encalados de mampostería y launa que destaca por conservar una recia torre campanario y una armadura interior de madera de sabina restaurada.','inventario_monumentos_pdf');
