INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','monumento','Núcleos de población de La Alberca','El término municipal incluye los siguientes núcleos de población: Las Casas del Conde y Prado Carreras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','monumento','Casco Histórico y Arquitectura Popular de la Sierra de Francia','Conjunto histórico-artístico nacional de primer orden que conserva de forma impecable su trama urbana medieval jalonada por casas con fachadas de entramado de madera de castaño, adobes encalados, plantas bajas de mampostería granítica berroqueña y solanas voladas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental templo del siglo XVIII edificado en sillería de cantería fina que presenta una gran cúpula sobre el crucero, un imponente púlpito de granito profusamente labrado y un retablo mayor barroco de madera dorada de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','iglesia','Santuario de Nuestra Señora de la Peña de Francia','Monasterio dominico fortificado alzado en el siglo XV a más de mil setecientos metros de altitud que destaca por su iglesia gótica de piedra rústica caliza, una recia torre campanario exenta y un claustro de severas líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37015','monumento','Núcleos de población de Aldea del Obispo','El término municipal incluye los siguientes núcleos de población: Castillejo de de Dos Casas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37015','monumento','Real Fuerte de la Concepción','Impresionante fortificación abaluartada de primer orden construida en el siglo XVIII bajo el diseño del ingeniero militar Jorge Próspero de Verboom, ejecutada en sillería de granito berroqueño de impecable factura formal con planta estrellada de estilo Vauban que defendía la frontera lusa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37015','iglesia','Iglesia Parroquial de San Sebastián','Templo renacentista del siglo XVI construido en sillería fina y mampostería que destaca por su portada de líneas clasicistas herrerianas y una recia torre campanario de tres cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37024','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo renacentista castellano ordinario del siglo XVI ejecutado en mampostería granítica que presenta una portada clasicista moldurada y un presbiterio cubierto por una bóveda de arista barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37029','monumento','Núcleos de población de Anaya de Alba','El término municipal incluye los siguientes núcleos de población: Galindo y Perahuy.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37029','iglesia','Iglesia Parroquial de San Juan','Edificación renacentista castellana del siglo XVI ejecutada mediante cajones de mampostería y verdugadas de ladrillo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37031','iglesia','Iglesia Parroquial de de Nuestra Señora de la Asunción','Templo gótico-renacentista del siglo XVI edificado con muros de mampostería granítica de la zona que presenta una interesante portada de orden plateresco atribuida a la influencia constructiva del foco salmantino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37032','monumento','Núcleos de población de Arapiles','El término municipal incluye los siguientes núcleos de población: Las Torres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37032','monumento','Monumento de los de los Arapiles','Monolito conmemorativo exento alzado en el siglo XIX sobre el cerro histórico de la batalla de los Arapiles de 1812, ejecutado en sillería de piedra rústica caliza de la dehesa para atestiguar la trascendencia del enfrentamiento hispano-luso-británico contra las tropas napoleónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37032','iglesia','Iglesia Parroquial de San Fabián y San Sebastián','Templo renacentista castellano ordinario del siglo XVI edificado mediante cajones de mampostería y verdugadas de ladrillo mudéjar que presenta una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37034','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo rural común del siglo XVI edificado mediante paramentos de pizarra rústica encalada que cuenta con un interior de nave única rematada en un presbiterio de planta cuadrada cubierto por una bóveda de arista barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37037','iglesia','Iglesia Parroquial de San Miguel','Sencillo edificio del siglo XVI levantado con paramentos encalados de pizarra rústica y barro que presenta una modesta espadaña de ladrillo visto situada a los pies de la nave única.','inventario_monumentos_pdf');
