INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37042','iglesia','Iglesia Parroquial de la Virgen de la Asunción','Edificación de filiación renacentista del siglo XVI levantada con sillarejos de granito y mampostería vista que presenta un ábside poligonal reforzado con contrafuertes exteriores y una portada de líneas clásicas muy sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37045','iglesia','Iglesia Parroquial de San Sebastián','Templo rural del siglo XVI modificado en el XVIII con muros de mampostería de pizarra rústica encalada en la Sierra de Francia que destaca por su techumbre mudéjar de madera con tirantes toscamente labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90497','iglesia','Iglesia Parroquial de la Asunción','Inmueble parroquial de traza sencilla del siglo XVI edificado en la raya portuguesa con paramentos de mampostería y cantería que cuenta con una nave única de tramos regulares y una espadaña lateral de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90498','iglesia','Iglesia Parroquial de Santiago Apóstol','Edificación rural ordinaria del siglo XVI ejecutada con muros de mampostería vista combinada con granito berroqueño en sus esquinas que alberga un coro alto de madera y una espadaña de dos cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','iglesia','Iglesia Parroquial de San Pedro','Pequeña edificación rural ordinaria del siglo XVI ejecutada con mampostería local encalada que presenta una estructura de nave única rematada por una modesta espadaña de ladrillo visto situada a los pies del templo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37082','iglesia','Iglesia Parroquial de San Pedro Apóstol','Edificio de gran envergadura del siglo XVI levantado mediante cajones de mampostería vista e hiladas de ladrillo de tradición mudéjar que presenta una fachada renacentista herreriana y una potente torre del reloj adosada al presbiterio cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37083','iglesia','Iglesia Parroquial de Santa María de los Ángeles','Joya de la arquitectura mudéjar castellana del siglo XV catalogada como excelencia comarcal que sorprende por su presbiterio cubierto por una riquísima techumbre de madera policromada con lacerías islámicas y un ábside de ladrillo visto con bandas horizontales ciegas.','inventario_monumentos_pdf');
