INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37007','monumento','Yacimiento Arqueológico de Castro de las Merchanas','Extraordinario poblado fortificado de origen vetón de la Segunda Edad del Hierro perfectamente musealizado que conserva su monumental muralla de piedra rústica y pizarra, sus fosos defensivos contra la caballería y una espectacular puerta de acceso adaptada a la topografía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37007','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental edificio herreriano del siglo XVI levantado enteramente en sillería de granito berroqueño que destaca por su fachada clasicista de severas líneas simétricas y una espaciosa nave única con un presbiterio majestuoso.','inventario_monumentos_pdf');
