INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37184','iglesia','Iglesia Parroquial de San Nicolás de Bari','Monumental templo del siglo XVI alzado en el corazón de las Arribes del Duero enteramente en sillería de granito berroqueño que destaca por su imponente torre campanario de tres cuerpos, sus portadas platerescas de fina talla y un presbiterio cubierto por complejas bóvedas estrelladas.','inventario_monumentos_pdf');
