INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37235','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo rural común del siglo XVI ejecutado en mampostería de la Tierra de Alba que cuenta con una nave única rematada en un presbiterio de planta cuadrada cubierto por una bóveda de arista barroca y una espadaña de dos vanos con tejadillo moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37236','iglesia','Iglesia Parroquial de San Pedro','Templo del siglo XVI levantado con cajones de mampostería granítica de la zona que cuenta con una nave de tramos regulares rematada en un presbiterio cupulado y una espadaña de dos vanos.','inventario_monumentos_pdf');
