INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37238','iglesia','Iglesia Parroquial de San Andrés','Templo de filiación renacentista castellana común del siglo XVI levantado en mampostería granítica que presenta una nave de tramos regulares y una espadaña de dos vanos con pináculos decorativos sobre los pies del edificio.','inventario_monumentos_pdf');
