INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37240','iglesia','Iglesia Parroquial de San Juan','Templo renacentista del siglo XVI construido en mampostería caliza y piedra arenisca que presenta una portada clasicista moldurada de líneas muy sobrias y un interior de nave única rematada por una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37241','iglesia','Iglesia Parroquial de San Lorenzo','Pequeño inmueble parroquial modificado en el siglo XVII que utiliza caliza y mampostería encalada, caracterizado por su espadaña de doble cuerpo y un interior austero compartimentado por arcos fajones.','inventario_monumentos_pdf');
