INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37244','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo gótico-renacentista del siglo XVI construido en mampostería granítica serrana que destaca por su portada clasicista moldurada y un presbiterio cubierto por una bóveda de arista barroca.','inventario_monumentos_pdf');
