INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37246','iglesia','Convento de las Madres Carmelitas Descalzas','Edificio religioso fundado en el siglo XVII en ladrillo visto y piedra que conserva una magnífica iglesia barroca con una cúpula sobre pechinas y una espléndida colección de pintura napolitana de la escuela de Luca Giordano.','inventario_monumentos_pdf');
