INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37247','iglesia','Iglesia Parroquial de la Asunción','Joya de la arquitectura románico-mudéjar castellana del siglo XIII catalogada como excelencia comarcal que destaca por su espectacular ábside semicircular de ladrillo visto ornamentado con tres bandas superpuestas de arquerías ciegas dobles de gran valor decorativo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37248','iglesia','Iglesia Parroquial de San Miguel','Templo rural común del siglo XVI ejecutado en mampostería granítica de la comarca de Vitigudino que cuenta con una nave única rematada en un presbiterio de planta cuadrada cubierto por una bóveda de arista barroca y una espadaña a los pies.','inventario_monumentos_pdf');
