INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','monumento','Plaza Mayor de Salamanca','El monumento barroco civil más espectacular y armónico de España, diseñado en el siglo XVIII por Alberto Churriguera en piedra franca de Villamayor, delimitado por arquerías de medio punto porticadas con medallones heráldicos labrados y presidido por el Ayuntamiento de líneas monumentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','monumento','Casa de las Conchas','Palacio nobiliario de finales del siglo XV que fusiona el estilo gótico tardío con elementos mudéjares y platerescos, único en el mundo por su fachada de sillería revestida con más de trescientas conchas de peregrino talladas en relieve que proyectan un juego de luces cambiante.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','monumento','Puente Romano sobre el Río Tormes','Monumental obra de ingeniería civil del siglo I d.C. construida en época imperial que conserva quince de sus arcos de medio punto originales ejecutados en gruesos sillares de granito berroqueño compactados sin argamasa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','iglesia','Iglesia y Convento de San Esteban (Los Dominicos)','Espectacular templo dominico iniciado en el siglo XVI que impresiona a nivel mundial por su fachada exterior concebida como un monumental retablo plateresco al aire libre tallado en piedra caliza de Villamayor con una minuciosidad propia de la orfebrería gótico-flamígera.','inventario_monumentos_pdf');
