INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49056','iglesia','Iglesia Parroquial de de la Asunción','Templo rural común del siglo XVI levantado con paramentos de mampostería caliza de la zona de la comarca de la Tierra del Pan que cuenta con una nave de tramos regulares rematada en un presbiterio y una espadaña de ladrillo.','inventario_monumentos_pdf');
