INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49064','iglesia','Iglesia Parroquial de San Julián','Templo del siglo XVI levantado con sillarejos de granito berroqueño sayagués que cuenta con una nave de tramos regulares y una espadaña de dos vanos con pináculos decorativos sobre los pies del edificio.','inventario_monumentos_pdf');
