INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental fábrica de traza románica del siglo XII profundamente reformada en los siglos XVI y XVIII que conserva una soberbia portada de transición de arcos apuntados labrada en sillería de granito y un interior cubierto por complejas bóvedas estrelladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','monumento','Castillo de Doña Urraca','Ruinas de la antigua fortaleza medieval alzada sobre el escarpado peñasco que corona la villa de la que se conservan potentes lienzos de muralla de mampostería granítica compacta integrados en el paisaje natural de las arribas.','inventario_monumentos_pdf');
