INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','monumento','Núcleos de población de Meis','El término municipal incluye los siguientes núcleos de población: Nogueira, Paradela, San Lorenzo, San Tomé y Armenteira.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','iglesia','Monasterio de Santa María de Armenteira','cumbre del monacato cisterciense fundado en el siglo XII que conserva una imponente iglesia abacial románica con un grandioso rosetón calado de sillería granítica berroqueña, bóvedas de crucería primitivas y un claustro renacentista de severa elegancia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','iglesia','Iglesia de San Tomé de Nogueira','templo románico rural de finales del siglo XII que destaca por su ábside rectangular de cantería regular, su portada occidental con arquivoltas molduradas sobre capiteles vegetales y una rica serie de canecillos historiados bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','palacio','Pazo de Quintáns','casona solariega barroca del siglo XVII construida en aparejo de sillería regular que presenta un portalón de acceso flanqueado por pináculos heráldicos, amplias solainas orientadas a los viñedos de albariño y una palomera circular exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','monumento','Núcleos de población de Moaña','El término municipal incluye los siguientes núcleos de población: Domaio, Meira, Tirán y Vilaboa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','iglesia','Iglesia de San Martiño de Moaña','magnífico ejemplar del románico marinero del siglo XII reformado en el siglo XVIII que conserva su planta original de cruz latina de sillería isódoma, una rica portada occidental de tres arquivoltas profundas con capiteles zoomorfos y canecillos historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','palacio','Pazo de Rosal de Meira','gran residencia hidalga del siglo XVII que presenta una fisionomía maciza construida en sólida sillería granítica con un monumental portalón de acceso adintelado, grandes escudos nobiliarios labrados en piedra noble y amplias solainas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','monumento','Petroglifos de Monte do Con','estación arqueológica prehistórica de la Edad del Bronce grabada sobre una gran loma de granito liso que muestra representaciones esquemáticas de armas, cérvidos y combinaciones circulares bien conservadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','monumento','Núcleos de población de Mondariz','El término municipal incluye los siguientes núcleos de población: Gargamala, Lougares, Meirol, Sabaxáns, Toutón y Vilar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','monumento','Castillo de Sobroso','imponente fortaleza medieval del siglo XII emplazada estratégicamente sobre una colina rocosa que conserva sus potentes murallas defensivas de sillería granítica regular, su torre del homenaje almenada, su patio de armas central con aljibe y su palacio señorial restaurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','monumento','Puente Medieval de Cernadela','majestuosa estructura civil de origen romano reconstruida en el siglo XV que salva el curso del río Tea mediante varios arcos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','iglesia','Iglesia de Santa Baia de Lougares','templo románico rural de finales del siglo XII que preserva su nave única original de cantería regular, una portada occidental con arquivoltas lisas apoyadas sobre capiteles historiados y una serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','monumento','Núcleos de población de As Neves','El término municipal incluye los siguientes núcleos de población: Batalláns, Cerdeira, Liñares, Rubiós, Setados y Taboexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','iglesia','Santuario de Nuestra Señora de la Openla (Taboexa)','templo de origen medieval profundamente reformado en el siglo XVIII que destaca por su emplazamiento sobre una peña rocosa, conservando una fachada barroca simétrica de sillería granítica gálica y una escalinata monumental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','monumento','Estación Arqueológica de las Mámoas de Cerdeira','necrópolis megalítica prehistórica situada en la meseta de la llanura de montaña que conserva varios túmulos funerarios con sus cámaras interiores de losas de pizarra rústica y granito bien definidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','palacio','Pazo de Liñares (Rubiós)','casona solariega barroca del siglo XVII construida en aparejo de cantería regular que presenta un portalón de acceso flanqueado por pináculos heráldicos, amplias solainas orientadas a los viñedos de condal y un antiguo palomar circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','monumento','Núcleos de población de Nigrán','El término municipal incluye los siguientes núcleos de población: Camos, Chandebrito, Panxón, Parada, Priegue y San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','iglesia','Templo Votivo del Mar (Panxón)','monumental obra cumbre del arquitecto Antonio Palacios edificada a mediados del siglo XX en un estilo ecléctico e historicista que fusiona el gótico flamígero y el románico mediante el empleo masivo de sillería de granito berroqueño y pizarra local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','monumento','Arco Visigótico de Panxón','vestigio prerrománico del siglo VII perteneciente a un antiguo templo desaparecido que destaca por su arco de herradura de perfecta ejecución, labrado en bloques isódomos de granito del país y empotrado en los muros del cementerio actual.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','palacio','Pazo de Cea','monumental conjunto palaciego barroco del siglo XVII edificado en aparejo de sillería regular que destaca por su fachada monumental con tres grandes escudos de armas familiares, amplias balconadas de forja gallega y una escalinata de piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','monumento','Puente Románico de A Ramallosa (Sector Nigrán)','paso civil medieval construido sobre el río Miñor en sillería de granito berroqueño que une los municipios de Nigrán y Baiona mediante una sucesión de arcos apuntados perfectamente conservados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36010','iglesia','Real Monasterio de Santa María de Oia','colosal cenobio medieval de la Orden del Císter fundado en el siglo XII a orillas del océano Atlántico que destaca por su imponente fachada barroca con aires de fortaleza, su iglesia abacial románica de tres naves y un majestuoso claustro de sillería granítica berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36010','monumento','Petroglifos de las Augas dos Galiñeiros','extraordinario conjunto de arte rupestre prehistórico de la Edad del Bronce que incluye grandes afloramientos graníticos grabados con representaciones esquemáticas de embarcaciones marítimas, armas de combate y combinaciones circulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36010','iglesia','Iglesia de San Miguel de Loureza','templo románico rural de finales del siglo XII modificado en época barroca que conserva su ábside rectangular primitivo de sillería isódoma perfecta, una portada occidental con arquivoltas lisas y una valiosa serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','monumento','Núcleos de población de Pazos de Borbén','El término municipal incluye los siguientes núcleos de población: Amoedo, Borbén, Cepeda, Moscoso, Nespereira y Xunqueiras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','iglesia','Iglesia de Santiago de Borbén','edificación religiosa del siglo XVIII adscrita al barroco rural que exhibe una fachada sobria con hornacina central para el santo patrón, cornisa moldurada de doble pináculo y una esbelta torre-campanario de dos cuerpos bien proporcionados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','monumento','Conjunto Etnográfico de Moscoso','agrupación de arquitectura popular tradicional que reúne una densa concentración de hórreos tradicionales de piedra y madera noble alineados junto a una red de molinos harineros hidráulicos que aprovechan el cauce del riachuelo local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','monumento','Cruceiro de Cepeda','monumento religioso exento del siglo XIX labrado en granito por canteros locales que presenta un fuste octogonal sobre gradería cuadrada, capitel decorado con motivos pasionales y un remate superior esculpido con la imagen tradicional de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','monumento','Núcleos de población de Poio','El término municipal incluye los siguientes núcleos de población: Combarro, Samieira, San Salvador, San Juan y Raxó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','monumento','Conjunto Histórico-Artístico de Combarro','extraordinario núcleo marítimo medieval excelentemente conservado que destaca por su entramado de calles de losas graníticas y su colosal alineación de más de treinta hórreos tradicionales construidos al borde del mar sobre rústicos pies de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','iglesia','Monasterio de San Juan de Poio','magno complejo monástico benedictino fundado en el siglo VII que exhibe una monumental fachada barroca churrigueresca, dos majestuosos claustros de sillería granítica gálica perfectamente conservados y una iglesia abacial con sillería de coro del gótico tardío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','iglesia','Hórreo Mayor del Monasterio de Poio','colosal monumento etnográfico e industrial menor construido en el siglo XVIII que constituye uno de los hórreos más grandes de Galicia al estar sustentado por tres hileras de robustos pies de cantería granítica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','iglesia','Iglesia de San Tomé de Samieira','templo parroquial de fábrica renacentista del siglo XVI que presenta una sobria fachada de cantería regular con portalón de arco de medio punto flanqueado por pilastras, planta de cruz latina y un retablo mayor dorado barroco. [1, 2]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','monumento','Pueblos en Pontevedra El bello municipio de Oia','Pueblos en Pontevedra El bello municipio de Oia se encuentra situado en la vertiente suroeste de la Comunidad Autónoma de Galicia, concretamente en la z...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','monumento','8 pueblos medievales en Pontevedra que puedes descubrir En el corazón de las Rías Baixas, Combarro es uno de los pueblos','8 pueblos medievales en Pontevedra que puedes descubrir En el corazón de las Rías Baixas, Combarro es uno de los pueblos cerca de Pontevedra ( provincia de Pontevedra ) más emblemáticos ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','iglesia','45 rincones mágicos QUE VER en PONTEVEDRA Provincia 40. Monasterio de Poio','45 rincones mágicos QUE VER en PONTEVEDRA Provincia 40. Monasterio de Poio ( Monasterio de San Xoán de Poio ) Monasterio de San Xoán de Poio (San Juan de Poio). monasterio benedictin...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36043','monumento','Núcleos de población de Ponte Caldelas','El término municipal incluye los siguientes núcleos de población: Anceu, Caritel, Forzáns, Insua, Taboadelo y Tourón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36043','monumento','Área Arqueológica de Tourón','colosal complejo de arte rupestre al aire libre de la Edad del Bronce que congrega excepcionales paneles de petroglifos grabados sobre afloramientos de granito berroqueño, destacando el "Laxe das Cruces" por sus complejas combinaciones circulares y escenas de caza con ciervos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36043','iglesia','Iglesia de Santa Eulalia de Ponte Caldelas','templo barroco del siglo XVIII construido con sillería regular que destaca por su fachada simétrica moldurada, su portalón flanqueado por pilastras cajeadas y una esbelta torrecampanario central rematada por un cupulino de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36043','monumento','Puente Medieval sobre el Río Verdugo','notable estructura civil erigida en sillería granítica que salva el curso fluvial mediante dos grandes arcos de medio punto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36043','palacio','Pazo de Anceu','casona hidalga de los siglos XVI y XVII que presenta una fisionomía maciza de muros perimetrales de piedra noble, un portalón de acceso adintelado con blasón heráldico y una solaina sobre robustas columnas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36042','monumento','Núcleos de población de Ponteareas','El término municipal incluye los siguientes núcleos de población: Angoares, Celeiros, Fontenla, Guláns, Padróns y Xinzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36042','monumento','Castro de Troña','extraordinario poblado fortificado de la Edad del Hierro y época romano-gala que corona un alto promontorio, preservando un complejo sistema defensivo de fosos, una muralla de mampostería en seco y las bases de más de treinta viviendas circulares indígenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36042','iglesia','Iglesia de San Miguel de Angoares','joya del románico rural de finales del siglo XII que destaca por su ábside semicircular perfecto de sillería isódoma, su portada occidental de tres arquivoltas molduradas sobre capiteles historiados y una valiosa serie de canecillos antropomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36042','monumento','Puente de los Remedios (San Roque)','monumental paso civil de origen medieval reformado en el siglo XVIII que cruza el río Tea mediante arcos apuntados ejecutados en sólida cantería granítica, conservando el característico perfil de lomo de asno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36042','iglesia','Convento de San Diego de Canedo','complejo monástico franciscano del siglo XVIII que exhibe una severa arquitectura barroca de líneas clasicistas, muros limpios de granito del país y una iglesia de planta basilical de gran sobriedad decorativa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','monumento','Núcleos de población de Pontevedra','El término municipal incluye los siguientes núcleos de población: Alba, Campañó, Lourizán, Mourente, Salcedo y Santa María de Xeve.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','iglesia','Basílica de Santa María la Mayor','cumbre del gótico tardío marinero y el plateresco renacentista del siglo XVI edificada por el Gremio de Mareantes que destaca por su colosal fachada-retablo tallada por Cornielis de Holanda, sus bóvedas de crucería estrellada y sus filigranas pétreas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','iglesia','Iglesia de la Virgen Peregrina','singular santuario barroco-neoclásico de finales del siglo XVIII diseñado con una innovadora planta en forma de concha de vieira que exhibe una fachada convexa flanqueada por dos torres gemelas y decorada con ricas esculturas figurativas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','monumento','Ruinas de Santo Domingo','restos consolidados de la iglesia de un convento gótico del siglo XIV declarados Monumento Nacional que conservan un imponente ábside pentagonal con elevados ventanales apuntados de tracería calada y una colección de laudas sepulcrales medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','iglesia','Convento e Iglesia de San Francisco','magno templo del gótico mendicante de los siglos XIV y XV que presenta una planta de cruz latina con un testero de tres ábsides poligonales cubiertos con bóveda de crucería y una sobria portada occidental flanqueada por arcos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','palacio','Pazo de Lourizán','monumental palacio modernista y ecléctico del siglo XIX proyectado por el arquitecto Jenaro de la Fuente que destaca por su deslumbrante fachada de sillería regular combinada con grandes ventanales acristalados, una escalinata imperial con estatuas y un gran invernadero de vidrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','monumento','Núcleos de población de O Porriño','El término municipal incluye los siguientes núcleos de población: Atios, Budiño, Cans, Pontellas y Torneiros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','monumento','Casa Consistorial de O Porriño','obra cumbre de la arquitectura civil palaciega del arquitecto Antonio Palacios edificada a principios del siglo XX en un estilo ecléctico e historicista regionalista que destaca por su monumental pórtico de arcos apuntados, su torreón central y el uso masivo de granito rosa local perfectamente labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','iglesia','Iglesia de San Estevo de Atios','edificación de origen románico profundamente reformada en época barroca que conserva de su antigua fábrica medieval la estructura de su ábside rectangular de sillería isódoma y una interesante colección de canecillos de proa bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','monumento','Yacimiento Paleolítico de Gándaras de Budiño','hito arqueológico referencial a nivel peninsular musealizado que conserva niveles de ocupación del Pleistoceno Superior con abundantes muestras de industria lítica bifacial excavadas directamente sobre terrazas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','monumento','Núcleos de población de Portas','El término municipal incluye los siguientes núcleos de población: Briallos, Lantaño, Romai y Portas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','iglesia','Iglesia de San Román de Romai','templo de origen románico del siglo XII modificado en el barroco que conserva su nave única medieval de sillería granítica, una portada occidental de arquivoltas lisas sobre capiteles de temática vegetal esquemática y un Agnus Dei labrado en el testero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','palacio','Pazo de Lantaño','gran residencia hidalga del siglo XVIII que presenta una planta rectangular maciza construida en sólida cantería regular con un monumental portalón de acceso adintelado, grandes escudos nobiliarios labrados en piedra noble y amplias solainas orientadas a los viñedos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','monumento','Cruceiro de Briallos','monumento etnográfico religioso exento del siglo XVIII labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior ornamentada con las imágenes de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','monumento','Viaducto de Madrid','monumental obra de ingeniería civil industrial inaugurada en 1876 que combina sillería granítica berroqueña en sus pilares con una colosal celosía metálica de hierro forjado que sobrevuela el casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','monumento','Viaducto de Pontevedra','estructura ferroviaria de hierro y piedra inaugurada en 1884 declarada Bien de Interés Cultural que cruza de forma aérea la villa con altas pilastras de sillería regular y tramos metálicos de gran esbeltez técnica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','iglesia','Convento de Vilavella','cenobio de monjas franciscanas fundado en el siglo XVI que conserva una magnífica','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','palacio','Pazo de Torre-Cedeira','gran conjunto palaciego barroco del siglo XVII de planta en U que exhibe una fachada monumental de sillería granítica perfectamente labrada con los blasones heráldicos de los marqueses y un jardín romántico con árboles centenarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','iglesia','Iglesia de Santiago de Redondela','templo de origen románico reedificado en el siglo XVI en estilo gótico tardío y barroco que presenta un interior de nave única cubierta por bóveda de crucería estrellada y un retablo mayor dorado churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','monumento','Yacimiento de Monte do Castro (Besomaño)','poblado fortificado de la Edad del Hierro excavado y musealizado que conserva tramos de su muralla defensiva construida en mampostería en seco junto a los cimientos circulares y cuadrangulares de varias viviendas indígenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','palacio','Pazo de Barrantes','residencia solariega barroca del siglo XVIII construida en aparejo de sillería granítica regular que destaca por su portalón fortificado con escudo heráldico de los llinajes Bouzas, sus amplias solainas corridas y sus viñedos de albariño protegidos por muros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','iglesia','Iglesia de Santa Baia de Ribadumia','templo de origen románico profundamente reformado en época barroca que conserva de su traza medieval la estructura de su ábside rectangular de sillería isódoma perfecta y una valiosa serie de canecillos geométricos. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','monumento','Núcleos de población de Rodeiro','El término municipal incluye los siguientes núcleos de población: Carboentes, Guillar, Negro, Salto, San Martiño de Asperelo y San Salvador de Camba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','palacio','Pazo de Camba','monumental conjunto palaciego fortificado del siglo XIV reconstruido en el siglo XVII que destaca por sus potentes murallas de sillería granítica gálica, su torre del homenaje almenada de planta cuadrada y sus portalones de armas adintelados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','iglesia','Iglesia de San Salvador de Camba','joya del románico rural de finales del siglo XII que destaca por su ábside semicircular perfecto de sillería regular con saeteras abocinadas, una portada occidental de arquivoltas molduradas sobre capiteles historiados zoomorfos y canecillos decorados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','monumento','Cruceiro de Carboentes','monumento etnográfico religioso exento del siglo XVIII labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior ornamentada con las imágenes de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','monumento','Núcleos de población de O Rosal','El término municipal incluye los siguientes núcleos de población: As Eiras, Marzán, Pancenteo, San Miguel y Tabagón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','monumento','Molinos de O Folón y O Picón','colosal conjunto etnográfico declarado Bien de Interés Cultural que congrega sesenta molinos harineros de agua construidos en cascada escalonada sobre la ladera de la montaña mediante muros de mampostería granítica y canales excavados en roca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','iglesia','Iglesia de Santa Mariña do Rosal','templo parroquial barroco del siglo XVIII proyectado con elegante traza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','palacio','Pazo de As Eiras','residencia hidalga fortificada del siglo XVII adaptada al estuario del Miño que presenta una estructura cuadrangular maciza de piedra regular, un portalón de acceso de medio punto blasonado y una solaina sobre robustas columnas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36049','palacio','Pazo de Pegullal','gran residencia solariega barroca del siglo XVIII edificada en aparejo de sillería granítica que destaca por su monumental portalón de acceso flanqueado por pináculos heráldicos, una solaina interior sobre robustas columnas pétreas y un antiguo palomar circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36049','iglesia','Iglesia de Santiago de Entenza','edificación de origen románico profundamente reformada en época barroca que conserva de su antigua fábrica medieval la estructura de su ábside rectangular de sillería isódoma perfecta y una interesante colección de canecillos geométricos.','inventario_monumentos_pdf');
