INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','iglesia','Iglesia de San Pedro de Ansemil','templo medieval de origen monástico que conserva una magnífica fábrica románica del siglo XII con una portada de arquivoltas apuntadas y una capilla gótica lateral del siglo XIV donde se custodian valiosos sepulcros hidalgos de la familia Deza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','palacio','Pazo de Des','gran residencia solariega barroca del siglo XVII de planta en L que cuenta con una colosal fachada de sillería granítica perfectamente labrada con los blasones de los condes de Grajal, grandes chimeneas monumentales y una palomera exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','monumento','Puente Medieval de Taboada','monumental estructura civil del siglo X modificada en el siglo XII que salva el curso del río Deza mediante un único arco apuntado de gran luz ejecutado con grandes bloques de sillería isódoma de granito berroqueño.','inventario_monumentos_pdf');
