INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90541','monumento','Puente de Comesaña','paso civil medieval construido sobre los cimientos de una antigua calzada romana que salva el riachuelo mediante arcos apuntados de sólida cantería de granito, conservando su trazado original con pavimento de losas pétreas.','inventario_monumentos_pdf');
