INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90544','iglesia','Iglesia de Santiago de Amoexa','joya del románico rural del siglo XII que destaca por su ábside semicircular perfecto de sillería regular con columnas adosadas, su portada occidental de arquivoltas profundas labradas y capiteles de rica iconografía zoomorfa.','inventario_monumentos_pdf');
