INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90545','monumento','Conjunto Etnográfico de Córneas','agrupación de arquitectura popular adaptada a la orografía montañosa que reúne viviendas de mampostería en seco, hórreos tradicionales con techumbres de paja o pizarra y antiguos molinos harineros alineados en el cauce fluvial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90545','monumento','Cruceiro de Martín','monumento religioso exento del siglo XIX labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre tres gradas cuadradas, capitel jónico moldurado y una cruz superior ornamentada con el relieve de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27901','monumento','Núcleos de población de Baralla','El término municipal incluye los siguientes núcleos de población: Aranza, Berselos, Costantín, Piñeira y Vale.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27901','iglesia','Iglesia de Santa María de Piñeira','templo de origen románico profundamente reformado en el siglo XVIII que conserva de su traza medieval el ábside rectangular de sillería granítica gálica y una colección de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27901','palacio','Pazo de Aranza','residencia hidalga fortificada de los siglos XVI y XVII levantada con muros macizos de mampostería de pizarra rústica y esquinales de granito berroqueño que conserva su portalón blasonado y una solaina corrida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27901','monumento','Puente Medieval de Covas','paso civil erigido en aparejo regular de piedra local que salva el curso del río Neira mediante un gran arco apuntado diseñado para el tránsito tradicional de las vías de arriería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','monumento','Núcleos de población de Barreiros','El término municipal incluye los siguientes núcleos de población: Cabarcos, Celeiro de Mariñaos, San Cosme de Barreiros y San Pedro de Benquerencia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','iglesia','Iglesia de San Cosme de Barreiros','edificación religiosa del siglo XVIII de traza neoclásica sobria construida con aparejo de sillería granítica que exhibe una fachada simétrica con hornacina central para el santo y una esbelta torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','palacio','Pazo de de Masma','gran casona solariega barroca del siglo XVII de planta rectangular que presenta un monumental portalón de acceso adintelado, escudos nobiliarios labrados en piedra noble y amplias galerías de madera para el secado del grano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','monumento','Cruceiro de Celeiro','monumento etnográfico exento del siglo XVIII labrado en granito por maestros canteros de la comarca de la Mariña que presenta un fuste octogonal sobre gradería cuadrada y una cruz superior con el relieve de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28001','iglesia','Monasterio de Santa María de Penamaior','cenobio medieval de la Orden del Císter fundado en el siglo XII que conserva su magnífica iglesia románica con tres ábsides semicirculares de cantería regular, capiteles','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28001','monumento','Puente de Cruzul','monumental estructura de ingeniería civil neoclásica de finales del siglo XVIII construida bajo el reinado de Carlos IV que destaca por sus elevados arcos de medio punto ejecutados en sillería regular caliza calavera y granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28001','palacio','Pazo de Oselle','conjunto palaciego señorial del siglo XVII adaptado a la orografía de los Ancares que cuenta con muros macizos de mampostería de pizarra rústica, portalón fortificado con escudo de armas y una capilla privada con retablo de tipo cajón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','monumento','Núcleos de población de Begonte','El término municipal incluye los siguientes núcleos de población: Baamonde, Bóveda, Carral, Gaizán, Pacios y Saavedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','iglesia','Iglesia de Santiago de Baamonde','templo de origen románico del siglo XII modificado en época barroca que conserva su portada occidental primitiva de arquivoltas molduradas, capiteles decorados con motivos vegetales y un calvario monumental exento en su recinto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','palacio','Pazo de Bóveda','gran conjunto palaciego barroco del siglo XVIII que cuenta con una colosal fachada de sillería regular de granito perfectamente labrada con los blasones heráldicos familiares, una amplia solaina y unos jardines cercados por murallas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','monumento','Cruceiro de Saavedra','joya del arte etnográfico religioso del siglo XVIII labrada en granito del país que presenta un pedestal moldurado sobre tres gradas, fuste estriado y una cruz superior ornamentada con las figuras exentas de Cristo Crucificado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','monumento','Núcleos de población de Bóveda','El término municipal incluye los siguientes núcleos de población: Freituxe, Guntín, Martín, Ribas Pequenas, Tuimil y Ver.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','palacio','Pazo de los Marqueses de Bóveda','monumental palacio solariega barroco del siglo XVIII de planta rectangular que exhibe una suntuosa fachada de sillería granítica perfectamente labrada, portalón fortificado con escudos de armas y una capilla privada consagrada a San Gil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','iglesia','Iglesia de San Juan de Martín','edificación románica rural de finales del siglo XII que preserva su nave única original de cantería regular, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','monumento','Hórreos de Tuimil','conjunto etnográfico de arquitectura popular tradicional integrado por una alineación de hórreos del tipo lucense edificados con pies de cantería y cerramientos mixtos de madera noble y pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','monumento','8 Pueblos medievales de Lugo que puedes conocer Becerreá Becerreá es uno de los pueblos de Lugo','8 Pueblos medievales de Lugo que puedes conocer Becerreá Becerreá es uno de los pueblos de Lugo ( provincia de Lugo ) cerca de Asturias que sorprende por su ubicación estratégica...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','monumento','Núcleos de población de Carballedo','El término municipal incluye los siguientes núcleos de población: Aguada, Chouselas, Furco, Lobelle, Marza, Oleiros y San Mamede de Lousada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','iglesia','Iglesia de San Juan de Cova','joya monumental del románico de finales del siglo XII emplazada en la ladera del río Miño que destaca por su ábside semicircular de sillería granítica berroqueña, su portada occidental de tres arquivoltas molduradas sobre capiteles historiados y una colección de canecillos antropomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','palacio','Pazo de Búbal','casona solariega fortificada del siglo XVII construida en aparejo de cantería regular que presenta un monumental portalón de acceso adintelado con los blasones labrados de los Enríquez, amplias solainas corridas y una torre defensiva desmochada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','monumento','Cruceiro de Lobelle','monumento etnográfico religioso exento del siglo XVIII labrado en granito del país que cuenta con una base moldurada sobre tres gradas cuadradas, fuste estriado y un capitel decorado con motivos pasionales coronado por la Virgen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','monumento','Núcleos de población de Castro de Rei','El término municipal incluye los siguientes núcleos de población: Ansemar, Bendia, Duancos, Loentia, Prevesos y Santa Locaia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','monumento','Castro de Viladonga','extraordinario poblado fortificado galaico-romano musealizado que conserva intacto su imponente sistema defensivo de varias murallas concéntricas de mampostería de pizarra, fosos excavados en el terreno y decenas de viviendas circulares indígenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','iglesia','Iglesia de San Salvador de Castro de Rei','templo parroquial barroco del siglo XVIII edificado en lo alto de la villa que destaca por su esbelta torre campanario de sillería regular, su portada neoclásica exenta de ornamentación pesada y un retablo churrigueresco de rica talla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','palacio','Pazo de de Viladonga','gran residencia solariega del siglo XVIII que presenta una planta rectangular maciza construida con aparejo mixto de losas de pizarra rústica y esquinales graníticos, provista de un gran blasón nobiliario labrado en la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','monumento','Núcleos de población de Castroverde','El término municipal incluye los siguientes núcleos de población: Bolaño, Cellán de Calvos, Masoucos, Soutomerille y Vilabade.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','iglesia','Iglesia de Santa María de Vilabade','monumental templo calificado como la "Catedral de Castroverde" edificado en el siglo XV en estilo gótico tardío con reformas barrocas que destaca por su gran pórtico de arquerías, sus bóvedas de crucería estrellada y un colosal retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','monumento','Torre del Homenaje de Castroverde','imponente vestigio fortificado de una fortaleza medieval del siglo XIV que se eleva más de veinte metros con gruesos muros de sillería regular caliza calavera y granito, conservando sus saeteras y los canecillos del desaparecido voladizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','iglesia','Iglesia de Santa María de Soutomerille','edificación de origen prerrománico en estado de ruina consolidada que conserva elementos de transición medieval como ventanas geminadas con arcos de herradura visigóticos y muros de aparejo irregular de pizarra local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','palacio','Pazo de Vilabade','residencia hidalga barroca del siglo XVII contigua al templo que presenta una fisionomía palaciega con portalón de armas adintelado flanqueado por pináculos heráldicos, grandes chimeneas monumentales y amplias balconadas de forja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','monumento','Núcleos de población de Cervantes','El término municipal incluye los siguientes núcleos de población: Castelo Frade, Doiras, Pando, San Román de Cervantes y Vilarello.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','monumento','Castillo de Doiras','imponente fortaleza medieval del siglo XV colgada de forma estratégica sobre una peña rocosa de los Ancares que conserva sus murallas de mampostería de pizarra rústica perfectly consolidadas, su torre del homenaje cuadrangular y su patio de armas central con aljibe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','monumento','Conjunto Etnográfico de Piornedo','singular poblado de alta montaña integrado por una densa concentración de pallozas tradicionales de origen prerrománico construidas con rústicos muros circulares de piedra y techumbres cónicas de paja de centeno adaptadas a las nevadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','iglesia','Iglesia de San Román de Cervantes','templo de origen románico profundamente reformado en el siglo XVIII que destaca por su severa arquitectura barroca de montaña con techumbre de losas de pizarra rústica, muros limpios de cantería y una espadaña de doble vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','monumento','Núcleos de población de Chantada','El término municipal incluye los siguientes núcleos de población: Brigos, Camporramiro, Mariz, Nogueira de Miño, Pesqueiras y San Salvador de Asma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','iglesia','Iglesia de San Salvador de Asma','cenobio medieval de origen benedictino del siglo XII que conserva una monumental iglesia románica con un magnífico ábside semicircular de sillería de granito gálica, una portada de arquivoltas profundas labradas y pinturas murales del siglo XVI.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','iglesia','Iglesia de Santa María de Pesqueiras','joya del románico rural del siglo XII oculta entre bosques que destaca por su ábside rectangular de cantería regular perfecta, su portada occidental de arquivoltas lisas sobre capiteles historiados zoomorfos y una valiosa serie de canecillos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','palacio','Pazo de de Mariz','gran conjunto palaciego barroco del siglo XVII de planta en U que exhibe una fachada monumental de sillería granítica perfectamente labrada con los blasones heráldicos de los llinajes gallegos, amplias solainas sobre arquerías y un antiguo palomar exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','monumento','Casco Histórico y Rúa de Fornelos','trazado urbano tradicional caracterizado por sus calles empedradas con losas graníticas, sus casas blasonadas de sillería y pizarra provistas de soportales tradicionales con arcos de medio punto protegidos por ordenanza patrimonial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90552','monumento','Núcleos de población de O Corgo','El término municipal incluye los siguientes núcleos de población: Farnadeiros, Folgosa, Laxosa, Marei, Sabarei y Santo Estevo de Folgosa.','inventario_monumentos_pdf');
