INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90552','palacio','Pazo de de Laxosa','casona solariega barroca del siglo XVII construida en aparejo de losas de pizarra rústica combinada con esquinales de granito que destaca por su portalón fortificado con escudo de armas familiar flanqueado por pináculos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90552','monumento','Puente Medieval de San Fiz','estructura civil erigida en sillería de granito y mampostería gruesa sobre el río Chamoso que salva el curso fluvial mediante dos arcos de medio punto provistos de potentes tajamares triangulares bien conservados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','monumento','Núcleos de población de Cospeito','El término municipal incluye los siguientes núcleos de población: Muimenta, Pino, Roás, Santa Cristina, Sisoi y Xustás.','inventario_monumentos_pdf');
