INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','iglesia','Iglesia de Santa María de Cospeito','templo parroquial barroco del siglo XVIII que exhibe una fachada monumental de cantería vista con hornacina central, cornisa moldurada de doble pináculo y una esbelta torrecampanario de dos cuerpos rematada por un cupulino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','palacio','Pazo de de Sistallo','gran conjunto palaciego barroco del siglo XVIII de planta rectangular que presenta una fachada monumental barroca con amplias balconadas de forja gallega, un portalón de acceso adintelado con grandes blasones heráldicos labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','monumento','Núcleos de población de Folgoso do Courel','El término municipal incluye los siguientes núcleos de población: Esperante, Meiraos, Seceda, Seoane do Courel y Vilamor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','monumento','Aldea Etnográfica de Seceda','singular núcleo rural de alta montaña excelentemente conservado que destaca por su trama urbana de losas graníticas y pizarra, reuniendo viviendas tradicionales unidas por pasadizos elevados de madera noble y cubiertas cónicas de pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','monumento','Castillo de Carbedo','restos de una imponente fortaleza medieval del siglo XII colgada de forma estratégica sobre una peña rocosa del Courel que conserva los basamentos de su torre vigía y tramos de los lienzos de la muralla defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','monumento','Ferrería de Locay','restos arqueológicos industriales e hidráulicos del siglo XVIII vinculados a la explotación tradicional del hierro que conservan las estructuras construidas en mampostería de pizarra, canales de captación y grandes tinos de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','iglesia','Iglesia de San Juan de Seoane','templo de origen románico profundamente reformado en el siglo XVIII que destaca por su severa arquitectura barroca de montaña con techumbre tradicional de losas de pizarra rústica, muros de mampostería vista de cuarcita local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28004','monumento','Núcleos de población de A Fonsagrada','El término municipal incluye los siguientes núcleos de población: Burón, Carballido, Lamas de Campos, San Martín de Suarna y Vilabol de Suarna.','inventario_monumentos_pdf');
