INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28004','iglesia','Iglesia de Santa María de la Fonsagrada','templo parroquial del siglo XVIII vinculado al Camino de Santiago Primitivo que destaca por su fachada neoclásica sobria construida con aparejo granítico regular, su planta de cruz latina y la célebre Fuentemagrada adosada al muro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28004','monumento','Caserío y Hórreos de Lamas de Campos','conjunto etnográfico de montaña integrado por una densa concentración de hórreos tradicionales de tipo asturgalaico con cerramientos de listones de madera noble y techumbres cónicas de paja o losas de pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','monumento','Núcleos de población de Foz','El término municipal incluye los siguientes núcleos de población: Cangas, Cordido, Fazouro, Nois, San Martiño de Mondoñedo y Vilaronte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','iglesia','Basílica de San Martiño de Mondoñedo','la catedral más antigua de España conservada en su fábrica románica de los siglos XI y XII que destaca por su monumental cabecera de tres ábsides semicirculares, sus capiteles historiados de rústica ejecución y un antipendio de piedra labrada único.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','monumento','Castro de Fazouro','poblado fortificado de la Edad del Hierro y época romano-gala excavado y musealizado al borde del mar Cantábrico que preserva la estructura de su muralla perimetral de mampostería en seco junto a varias viviendas cuadrangulares indígenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','palacio','Pazo de de de Conde','gran residencia solariega barroca del siglo XVIII que presenta una fachada monumental de sillería granítica gálica perfectamente labrada, grandes escudos heráldicos exentos de las familias nobles y amplias balconadas de forja gallega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','iglesia','Iglesia de San Xiao de Cordido','templo románico rural de finales del siglo XII profundamente modificado en época barroca que conserva de su traza medieval la estructura de su ábside rectangular de sillería isódoma perfecta y una valiosa serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','monumento','Núcleos de población de Friol','El término municipal incluye los siguientes núcleos de población: Carballo, Cotá, Narla, San Cibrao da Pregación, Xiá y Guldriz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','monumento','Torre de Friol (Fortaleza de San Paio de Narla)','imponente complejo fortificado medieval reedificado tras las revueltas irmandiñas en el siglo XV que alberga una soberbia torre del homenaje cuadrangular de sillería granítica gálica y un cuerpo residencial musealizado con patios porticados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','palacio','Pazo de Miraz','gran residencia solariega del siglo XVII que presenta una fisionomía maciza rematada por almenas defensivas de tipo medieval, un portalón de acceso con escudo de armas de los llinajes Saavedra y una capilla barroca exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','iglesia','Iglesia de San Anxo de Cotá','edificación románica de finales del siglo XII que preserva su nave única original de sillería isódoma perfecta, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','monumento','Núcleos de población de Guitiriz','El término municipal incluye los siguientes núcleos de población: Lagostelle, Parga, Roca, San Breixo de Parga, Trasparga y Vilar de Donas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','monumento','Castillo de Parga','restos monumentales de una fortaleza defensiva del siglo XIV que domina la villa conservando potentes lienzos de muralla de mampostería granítica, la base de la torre del homenaje y mazmorras excavadas directamente en la roca natural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','iglesia','Iglesia de San Breixo de Parga','joya del románico rural del siglo XII que destaca por su ábside rectangular de cantería regular perfecta, su portada occidental de arquivoltas profundas labradas y capiteles historiados zoomorfos bien conservados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','monumento','Mesón y Puente de San Alberte','conjunto histórico civil integrado por un puente medieval del siglo XIV de arcos apuntados ejecutados en sólida sillería granítica','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27024','monumento','Núcleos de población de O Incio','El término municipal incluye los siguientes núcleos de población: Hospital do Incio, Mao, Pacios, Reboiro, Trascastro y Vilasouto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27024','iglesia','Iglesia de San Pedro de Hospital','joya cumbre del románico gallego del siglo XII construida íntegramente en mármol local extraído de la comarca que destaca por su monumental ábside rectangular, su torre-campanario exenta y una portada con tímpano esculpido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27024','monumento','Necrópolis Megalítica de Santa Mariña','complejo arqueológico prehistórico de la Edad del Bronce situado en la meseta de la llanura que conserva varios túmulos funerarios con sus cámaras interiores de losas de pizarra rústica bien definidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27024','palacio','Pazo de O de O Incio','residencia palaciega señorial de los siglos XVI y XVII que presenta una fisionomía maciza construida con aparejo mixto de losas de pizarra rústica y esquinales graníticos provista de un gran blasón nobiliario labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','monumento','Núcleos de población de Láncara','El término municipal incluye los siguientes núcleos de población: Armea, Carracedo, Cedrón, Láncara, Monseiro, Oleiros y Toirán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','iglesia','Iglesia de San Martiño de Oleiros','templo de origen románico del siglo XII que conserva su nave única de sillería granítica, una portada occidental de dos arquivoltas molduradas sobre capiteles vegetales y una rica serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','palacio','Pazo de Láncara','casona solariega barroca del siglo XVIII construida con aparejo de losas de pizarra rústica y esquinales de granito berroqueño que destaca por su portalón fortificado con escudo de armas flanqueado por pináculos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','monumento','Puente Medieval de Carracedo','estructura civil erigida en sillería de granito que salva el curso del río Neira mediante arcos apuntados perfectamente consolidados, habiendo servido históricamente para asegurar el tránsito tradicional de las vías de arriería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','monumento','Núcleos de población de Lourenzá','El término municipal incluye los siguientes núcleos de población: Santo Tomé, San Adriano, San Julián y Vilanova de Lourenzá.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','iglesia','Monasterio de San Salvador de Lourenzá','magno complejo monástico fundado por el Conde Santo en el siglo X cuya fachada de la iglesia abacial, proyectada por Fernando de Casas Novoa en el siglo XVIII, sirvió como modelo directo para la fachada del Obradoiro de Santiago de Compostela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','monumento','Sepulcro del Conde Santo','monumento funerario del siglo VI de sillería caliza calavera importada que se custodia en la capilla conventual del monasterio y destaca por sus relieves paleocristianos de gran valor iconográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','palacio','Pazo de Tovar','monumental joya de la arquitectura civil fortificada de transición del gótico tardío al renacimiento del siglo XVI que presenta dos torres almenadas con ventanas góticas de tracería calada y un imponente portalón heráldico labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Núcleos de población de Lugo','El término municipal incluye los siguientes núcleos de población: Albeiros, Bocamaos, Coeses, Esperante, Labio, Meilán, Ombreiro, Pías, Tirimol y San Xoán de Pena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Muralla Romana de Lugo','colosal fortificación militar romana construida a finales del siglo III que está declarada Patrimonio de la Humanidad por la UNESCO al conservar íntegro su perímetro de más de dos kilómetros ejecutado con paramentos de lajas de pizarra rústica y sillería granítica berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','catedral','Catedral de Santa María de Lugo','magno templo iniciado en el siglo XII que fusiona el románico, gótico y neoclásico, destacando por su fachada principal','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Puente Romano de Lugo','monumental estructura de ingeniería civil del siglo I reformada en época medieval que formaba parte de la Vía XIX y salva el curso del río Miño mediante arcos de medio punto construidos con grandes sillares isódomos almohadillados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Termas Romanas de Lugo','complejo termal público de época imperial situado junto al cauce fluvial que preserva la sala del apodyterium con hornacinas perimetrales de sillería regular destinadas al descanso y baños de vapor sanitarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','iglesia','Iglesia de San Pedro (Antiguo Convento de San Francisco)','destacado templo del gótico mendicante de los siglos XIV y XV que presenta una planta de cruz latina con un testero de tres ábsides poligonales cubiertos con bóveda de crucería y un bellísimo claustro gótico calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','monumento','Núcleos de población de Meira','El término municipal incluye los siguientes núcleos de población: Meira y Seixosmil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','iglesia','Iglesia del Monasterio de Santa María de Meira','monumental templo abacial de la Orden del Císter consagrado en 1258 que constituye una de las obras cumbres del románico de transición en Galicia al exhibir una severa fachada occidental con un gran rosetón calado y un interior de tres naves de sillería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','monumento','Pedregal de Irimia','monumento natural e hito geográfico referencial que consiste en un colosal embudo de bloques asimétricos de cuarcita local bajo el cual fluyen las primeras aguas que dan nacimiento al río Miño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','monumento','Cruceiro de Meira','monumento etnográfico exento del siglo XVIII labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior ornamentada con las imágenes de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','monumento','Núcleos de población de Mondoñedo','El término municipal incluye los siguientes núcleos de población: Argomoso, Lindín, Maariz, Oirán, Sasdónigas, Vilamor y Viloalle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','catedral','Catedral de la Asunción de Mondoñedo','Monumental templo iniciado en el siglo XIII declarado Patrimonio de la Humanidad que fusiona una fachada románica provista de un gran rosetón gótico occidental calado con esbeltas torres barrocas del siglo XVIII labradas en granito del país.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','iglesia','Santuario de Nuestra Señora de los Remedios','Templo barroco de mediados del siglo XVIII proyectado con elegante planta de cruz latina que destaca por sus dos esbeltas torres gemelas simétricas de sillería granítica y un espectacular retablo mayor churrigueresco de rica talla policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','palacio','Palacio Episcopal','Edificio civil de fábrica barroca del siglo XVIII que delimita la plaza catedralicia y exhibe un monumental portalón de acceso adintelado con los grandes blasones heráldicos de los obispos labrados minuciosamente en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','iglesia','Monasterio de Alcántara','Antiguo cenobio concepcionista de los siglos XVII y XVIII edificado con aparejo mixto de pizarra rústica y esquinales graníticos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','monumento','Puente del Pasatiempo','Estructura civil de origen medieval construida en sólida cantería sobre el río Valiñadares que destaca por salvar el curso fluvial mediante un robusto arco de medio punto vinculado históricamente al Mariscal Pardo de Cela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','monumento','Núcleos de población de Monforte de Lemos','El término municipal incluye los siguientes núcleos de población: Baamorto, Chavaga, Guntín, Marcelle, Moreda, Ribas Altas, Seoane y Tor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','monumento','Colegio de Nuestra Señora de la Antigua (Los Escolapios)','Magno y monumental complejo herreriano de finales del siglo XVI conocido como el "Escorial Gallego" que exhibe una colosal fachada de sillería regular granítica perfectamente simétrica, una fastuosa iglesia con cúpula sobre pechinas y un majestuoso claustro procesional calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','iglesia','Monasterio de San Vicente del Pino','Cenobio medieval benedictino que corona el monte de Lemos con su imponente iglesia del gótico tardío de finales del siglo XVI, provista de una severa portada neoclásica exenta de ornamentación superflua y un claustro neoclásico de sillería regular perfectamente conservado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','monumento','Torre del Homenaje de Monforte','Esbelto baluarte fortificado de planta cuadrada perteneciente al antiguo castillo de los Condes de Lemos del siglo XIV que se eleva treinta metros de altura con potentes lienzos de sillería granítica gálica y estrechas saeteras defensivas practicables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','monumento','Puente Viejo','Estructura civil de origen romano reconstruida en el siglo XVI por orden de la casa condal para salvar el curso del río Cabe mediante seis arcos de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','palacio','Pazo de Tor','Monumental palacio solariego barroco del siglo XVIII perfectamente conservado que congrega una de las mejores colecciones de mobiliario e instrumental tradicional al preservar intacta su estructura hidalga de sillería granítica y sus portalones de armas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','monumento','Núcleos de población de Monterroso','El término municipal incluye los siguientes núcleos de población: Bidouredo, Esporiz, Fente, Frameán, Ligonde, Novelúa, Pedraza y Val de Sangorza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','iglesia','Iglesia de San Cristovo de Novelúa','Joya del románico rural de finales del siglo XII vinculada a la orden compostelana que destaca por su ábside semicircular perfecto de sillería regular, su portada occidental de arquivoltas profundas labradas con motivos vegetales y capiteles zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','palacio','Pazo de de Lameiros','Residencia solariega fortificada de los siglos XVI y XVII que presenta una fisionomía maciza cuadrangular levantada con gruesos muros de mampostería de pizarra rústica y esquinales de granito berroqueño con una solaina corrida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','monumento','Cruceiro de Ligonde','Monumento etnográfico religioso exento del siglo XVII vinculado al Camino de Santiago Francés que se erige sobre una base moldurada de cantería y destaca por su fuste labrado con los motivos tradicionales de la Pasión de Cristo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','monumento','Núcleos de población de Muras','El término municipal incluye los siguientes núcleos de población: Ambosores, Balsa, Viveiro, Irixoa, Muras y Silán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','iglesia','Iglesia de Santa María de Muras','Templo parroquial del siglo XVIII adscrito al barroco rural de montaña que destaca por su techumbre tradicional de losas de pizarra rústica, sus gruesos muros de mampostería vista de cuarcita local y una esbelta espadaña de doble cuerpo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','monumento','Conjunto Etnográfico de Silán','Agrupación de arquitectura popular adaptada a la alta montaña que reúne una densa concentración de hórreos tradicionales lucenses edificados con pies de cantería y cerramientos mixtos de listones de madera noble y pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','monumento','Cruceiro de Viveiro','Modesto ejemplar religioso exento del siglo XIX labrado en granito del país por canteros locales que muestra un pedestal moldurado sobre tres gradas cuadradas y una cruz superior ornamentada con las figuras de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','monumento','Núcleos de población de Navia de Suarna','El término municipal incluye los siguientes núcleos de población: Barcia, Castañedo, Muñís, Rao, Ribón y Son.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','monumento','Castillo de Navia (A Pobra de Navia)','fortaleza medieval del siglo XI reedificada en el siglo XV tras las revueltas irmandiñas que se asienta sobre una roca madre y conserva su imponente torre del homenaje construida con gruesos muros de mampostería de pizarra rústica y esquinales graníticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','monumento','Puente Medieval de Navia de Suarna','monumental estructura civil de origen romano reconstruida en el siglo XIV que salva el curso del río Navia mediante un único arco apuntado de colosal luz ejecutado con aparejo irregular de pizarra local y cuarcita.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','monumento','Conjunto Etnográfico de las Pallozas de Rao','agrupación singular de arquitectura popular de alta montaña integrada por viviendas de origen prerrománico con rústicos muros circulares de piedra y techumbres cónicas de paja de centeno perfectamente adaptadas al clima de los Ancares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27035','iglesia','Iglesia de San Salvador de Negueira','templo parroquial barroco del siglo XVIII de carácter rural montañés que resalta por su techumbre de losas de pizarra rústica, una fachada severa de cantería y un porche cubierto destinado a proteger a los fieles de las inclemencias climáticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27035','palacio','Pazo de Marentes','residencia solariega fortificada del siglo XVII levantada en aparejo irregular de pizarra local que presenta una fisionomía maciza de muros limpios, portalón adintelado con escudo de armas familiares labrado en piedra y una solaina de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27035','monumento','Hórreos y Canastros de Ouviaño','conjunto etnográfico que reúne estructuras tradicionales destinadas al almacenamiento del cereal construidas con pies y bases de piedra pizarra combinadas con cerramientos de listones de madera de sabina y cubiertas cónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','monumento','Núcleos de población de Ourol','El término municipal incluye los siguientes núcleos de población: Ambosores, Bravos, Merille, Miñotos, Ourol y San Pantaleón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','iglesia','Iglesia de San Pantaleón de Cabanas','edificación de origen medieval reformada en época barroca que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','palacio','Pazo de Merille','gran casona hidalga del siglo XVII de planta rectangular que exhibe una fachada de mampostería concertada, un portalón de acceso provisto de pináculos heráldicos y grandes escudos nobiliarios labrados en piedra noble del país.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','monumento','Cruceiro de Ourol','monumento etnográfico religioso exento del siglo XIX labrado en granito por maestros canteros de la comarca que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior ornamentada con el relieve de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','monumento','Núcleos de población de Outeiro de Rei','El término municipal incluye los siguientes núcleos de población: Aspai, Bonxe, Candai, Guillar, Martul, Robra, Silvarrei y Sobrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','palacio','Torre de Sobrada (Pazo de Sobrada)','esbelta torre del homenaje de planta cuadrada perteneciente a una fortaleza medieval del siglo XV que conserva sus potentes lienzos defensivos ejecutados en sillería granítica gálica y estrechas saeteras con fines de vigilancia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','iglesia','Iglesia de San Martiño de Guillar','joya del románico rural de finales del siglo XII que destaca por su ábside semicircular perfecto de cantería regular, su portada occidental con arquivoltas molduradas sobre capiteles vegetales y una rica serie de canecillos historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','palacio','Pazo de de Mirapeixe','conjunto palaciego señorial del siglo XVIII edificado en aparejo regular que cuenta con un monumental portalón de acceso flanqueado por pináculos heráldicos, amplias solainas orientadas al valle sobre columnas pétreas y una capilla barroca privada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','monumento','Núcleos de población de Palas de Rei','El término municipal incluye los siguientes núcleos de población: Augas Santas, Carboeiro, Curbián, Ferreira de Pallares, Pambre, Vilar de Donas y San Xulián do Camiño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','monumento','Castillo de Pambre','la fortaleza medieval mejor conservada de Galicia erigida en el siglo XIV por Gonzalo Ozores de Ulloa que destaca por sus murallas defensivas con torres cuadrangulares en los ángulos, su torre del homenaje central almenada y muros de sillería granítica isódoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','iglesia','Iglesia de San Salvador de Vilar de Donas','joya monumental de la Orden de Santiago declarada Monumento Nacional que conserva una magnífica fábrica románica del siglo XII con una portada de arquivoltas profusamente esculpidas y unas extraordinarias pinturas murales góticas del siglo XIV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','iglesia','Iglesia de San Xulián do Camiño','templo románico rural de finales del siglo XII estrechamente vinculado al Camino de Santiago Francés que preserva su nave única original, una portada occidental de arquivoltas lisas y una notable serie de canecillos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','palacio','Pazo de Mariñao','gran residencia palaciega barroca del siglo XVIII que cuenta con una colosal fachada de sillería granítica perfectamente labrada con los blasones heráldicos de los llinajes gallegos, amplias balconadas de forja y un antiguo palomar exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','monumento','Este es el pueblo más pobre de la provincia de Lugo Sin embargo, en el lado opuesto, al final de la lista, se encuentran','Este es el pueblo más pobre de la provincia de Lugo Sin embargo, en el lado opuesto, al final de la lista, se encuentran los municipios más rurales de Lugo ( provincia de Lugo ) , y ...','inventario_monumentos_pdf');
