INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','monumento','Núcleos de población de Pantón','El término municipal incluye los siguientes núcleos de población: Deade, Ferreira de Pantón, Frontón, Pombeiro, San Fiz de Cangas, Toiriz y Tuiriz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','iglesia','Monasterio de Santa María de Ferreira de Pantón','monumental cenobio cisterciense femenino fundado en el siglo XII que destaca por conservar su iglesia románica original con un ábside semicircular de sillería granítica perfecta, capiteles historiados y un claustro renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','iglesia','Iglesia de San Vicente de Pombeiro','joya románica de finales del siglo XII emplazada en los cañones del Sil que presenta una planta basilical de tres naves, una fachada occidental con portada de tres arquivoltas y valiosas pinturas murales renacentistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','iglesia','Iglesia de San Fiz de Cangas','templo románico rural de finales del siglo XII que destaca por su ábside rectangular de cantería regular, su portada occidental moldurada sobre capiteles de temática vegetal y una excelente colección de canecillos esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','palacio','Pazo de Maside','gran conjunto palaciego barroco del siglo XVII de planta cuadrangular maciza que exhibe una fachada monumental de sillería de granito con los escudos heráldicos de los llinajes locales y una torre defensiva desmochada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','monumento','Núcleos de población de Paradela','El término municipal incluye los siguientes núcleos de población: Aldosende, Barán, Ferreiros, Francos, Laxe, Loio y San Facundo de Ribas de Miño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','iglesia','Iglesia de San Facundo de Ribas de Miño','obra cumbre del románico de la Ribeira Sacra declarada Monumento Nacional que destaca por sus monumentales arcos de descarga interiores, su ábside semicircular de sillería de granito y pinturas murales del siglo XIV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','iglesia','Iglesia de Santa María de Ferreiros','templo románico del siglo XII estrechamente vinculado al Camino de Santiago Francés que conserva su portada occidental de arquivoltas sencillas, muros de cantería regular y una rica serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','palacio','Pazo de de Barán','casona solariega barroca del siglo XVII construida en aparejo de losas de pizarra rústica y esquinales graníticos que presenta un portalón de acceso flanqueado por pináculos heráldicos y amplias solainas sobre arquerías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27044','monumento','Núcleos de población de A Pastoriza','El término municipal incluye los siguientes núcleos de población: Baltar, Bretoña, Cadavedo, Crecente, Gueimonde, Regueira y Úbeda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27044','iglesia','Iglesia de Santa María de Bretoña','templo parroquial edificado sobre la sede del antiguo obispado medieval de los britones que presenta reformas barrocas del siglo XVIII y conserva muros de cantería regular, una espadaña esbelta y un retablo mayor policromado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27044','palacio','Pazo de de Gueimonde','gran residencia solariega del siglo XVII de planta rectangular que exhibe una fachada de mampostería concertada de pizarra combinada con granito, portalón adintelado provisto de grandes escudos nobiliarios labrados en piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27044','monumento','Cruceiro de Úbeda','monumento etnográfico religioso exento del siglo XVIII labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior con el relieve de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','monumento','Núcleos de población de Pedrafita do Cebreiro','El término municipal incluye los siguientes núcleos de población: Cebrero, Fonfría, Hospital, Liñares, Pacios y Zanfoga.','inventario_monumentos_pdf');
