INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','monumento','Conjunto Etnográfico de las Pallozas del Cebrero','singular poblado de alta montaña que congrega varias viviendas tradicionales e industriales menores de origen prehistórico construidas con rústicos muros circulares de piedra y techumbres cónicas de paja de centeno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','iglesia','Iglesia de Santo Estevo de Liñares','edificación románica rural del siglo XII profundamente reformada que conserva de su traza medieval la estructura de su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27046','monumento','Núcleos de población de Pol','El término municipal incluye los siguientes núcleos de población: Andión, Arcos, Caraño, Luaces, Milleirós y Mosteiro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27046','iglesia','Iglesia de San Martiño de Caraño','edificación de origen medieval reformada en el siglo XVIII que conserva de su antigua fábrica románica la estructura del ábside rectangular de sillería granítica gálica y una valiosa serie de canecillos lisos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27046','palacio','Pazo de de Luaces','casona solariega barroca del siglo XVII construida en aparejo de losas de pizarra rústica combinada con esquinales graníticos que presenta un portalón de acceso flanqueado por pináculos heráldicos y amplias solainas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27046','monumento','Cruceiro de Mosteiro','monumento etnográfico exento del siglo XIX labrado en granito por maestros canteros de la comarca que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior con el relieve de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','monumento','Núcleos de población de A Pobra do Brollón','El término municipal incluye los siguientes núcleos de población: Castroncelos, Fornelos, Lamaigrexa, Óutara, Salcedo y Vilachá.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','monumento','Yacimiento del Castro de San Lourenzo','poblado fortificado de la Edad del Hierro y época medieval','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','monumento','Bodegas Tradicionales de Vilachá','extraordinario conjunto de arquitectura popular que reúne decenas de bodegas centenarias construidas con rústicos muros de piedra y techumbres de losas de pizarra, destinadas a la elaboración tradicional del vino de la Ribeira Sacra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','iglesia','Iglesia de San Martiño de de Lamaigrexa','templo parroquial barroco del siglo XVIII que exhibe una fachada monumental de cantería regular con una esbelta torrecampanario de dos cuerpos bien proporcionados y un retablo mayor churrigueresco de rica talla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','monumento','Núcleos de población de A Pontenova','El término municipal incluye los siguientes núcleos de población: Conforto, Vilaboa, Vilameá, Vilaoudriz y Xudán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','monumento','Hornos de Calcinación de Vilaoudriz','monumental conjunto de arqueología industrial minera de principios del siglo XX que congrega antiguos hornos construidos con gruesos muros de mampostería de pizarra rústica destinados al tratamiento tradicional del mineral de hierro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','iglesia','Santuario de Santa María de Conforto','templo de peregrinación barroco del siglo XVIII proyectado con elegante planta de cruz latina que destaca por su fachada neoclásica simétrica de cantería regular, su esbelta espadaña y un retablo mayor dorado churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','palacio','Pazo de de Vilameá','gran casona hidalga del siglo XVII de planta rectangular adaptada a la orografía montañosa que presenta muros macizos de mampostería vista, portalón adintelado con escudo de armas familiares labrado en piedra y amplias solainas de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27049','monumento','Núcleos de población de Portomarín','El término municipal incluye los siguientes núcleos de población: Bagude, Cortapezas, Fiz de Rozas, Gonzar, San Nicolao y San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27049','iglesia','Iglesia de San Juan (San Nicolao)','monumental templo-fortaleza románico tardío de finales del siglo XII erigido por la Orden de San Juan de Jerusalén que fue trasladado piedra a piedra tras la construcción del embalse, destacando por sus almenas defensivas de sillería granítica berroqueña y un colosal rosetón calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27049','iglesia','Iglesia de San Pedro','edificación románica de finales del siglo XII reconstruida en el nuevo emplazamiento de la villa que conserva una magnífica portada occidental con arquivoltas profundas labradas sobre capiteles historiados de gran valor artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27049','palacio','Pazo del General Berbetoros','residencia palaciega barroca del siglo XVII trasladada desde el antiguo núcleo urbano inundado que presenta una estructura cuadrangular maciza de piedra regular con un portalón de acceso de medio punto blasonado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27049','monumento','Puente Medieval sobre el Río Miño','restos de la antigua estructura civil sumergida cuyos arcos apuntados de sólida cantería granítica se hacen visibles durante las épocas de bajo caudal del embalse de Belesar como testimonio histórico del Camino de Santiago Francés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','monumento','Núcleos de población de Quiroga','El término municipal incluye los siguientes núcleos de población: Augas Mestas, Hospital, Pacios de Mondelo, Quintá de Lor, San Clodio y Sequeiros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','monumento','Túnel Romano de Montefurado','colosal obra de ingeniería minera del siglo II excavada directamente en la roca viva granítica de la montaña por orden del emperador Trajano para desviar el curso del río Sil y extraer el oro depositado en sus sedimentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','monumento','Castillo de Torrenovaes','restos fortificados de una imponente fortaleza medieval de la Orden de San Juan de Jerusalén que conserva su torre del homenaje cuadrangular de mampostería de pizarra rústica y esquinales graníticos junto a lienzos defensivos perimetrales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','iglesia','Iglesia de San Juan de Hospital','templo de origen románico profundamente reformado en el siglo XVIII que destaca por albergar en su interior capiteles tallados con motivos vegetales, laudas sepulcrales de los caballeros hospitalarios y una severa fachada con espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','palacio','Pazo de Pacios de Mondelo','residencia solariega barroca del siglo XVIII que presenta una fisionomía maciza adaptada a los bancales de viñedos con un monumental portalón adintelado provisto de grandes escudos heráldicos labrados en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27056','monumento','Puente Viejo de Rábade','estructura civil de origen medieval reconstruida en el siglo XVIII que salva el curso del río Miño mediante una sucesión de robustos arcos de medio punto construidos con grandes bloques de sillería granítica berroqueña y tajamares triangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27056','iglesia','Iglesia Parroquial de San Vincenzo','edificación religiosa del siglo XX de líneas historicistas y neoclásicas que aprovecha sillería regular caliza calavera y granito','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','monumento','Núcleos de población de Ribas de Sil','El término municipal incluye los siguientes núcleos de población: Nogueira, Peites, Rairos, Ribas de Sil, Torbeo y San Clodio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','iglesia','Abadía de San Clodio','antiguo complejo monástico benedictino medieval profundamente reformado en el siglo XVIII que conserva su iglesia abacial de sillería granítica regular con una sobria fachada barroca, una esbelta espadaña de doble cuerpo y un claustro procesional bajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','iglesia','Iglesia de Santa María de Torbeo','joya del románico rural de finales del siglo XII que destaca por su ábside semicircular perfecto de cantería regular, su portada occidental con arquivoltas molduradas sobre capiteles vegetales y una rica serie de canecillos historiados bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','monumento','Puente de Hierro de San Clodio','monumental estructura civil de ingeniería industrial inaugurada en 1883 para el ferrocarril que destaca por combinar altas pilastras de sillería granítica berroqueña con una colosal celosía metálica de hierro forjado que sobrevuela el curso del río Sil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','monumento','Núcleos de población de Riotorto','El término municipal incluye los siguientes núcleos de población: Aldurfe, Espasande, Galegos, Meilán, Riotorto y Santa Marta de Meilán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','monumento','Conjunto Etnográfico de los Mazos de Riotorto','agrupación singular de arquitectura popular e industrial hidráulica menor que reúne antiguos talleres de herreros tradicionales construidos con rústicos muros de mampostería de pizarra, los cuales conservan los canales de agua y los grandes mazos para el forjado del hierro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','iglesia','Iglesia de San Pedro de Riotorto','templo parroquial del siglo XVIII inscrito en el estilo barroco rural de montaña que cuenta con muros de mampostería granítica vista, una portada de arco de medio punto rematada por una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','monumento','Mazo de de Ferreiravella','resto arqueológico fabril hidráulico perfectamente conservado que consta de una estructura de piedra local adaptada al riachuelo destinada a la producción tradicional de herramientas agrícolas desde época medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','monumento','Núcleos de población de Samos','El término municipal incluye los siguientes núcleos de población: Castroncán, Freijo, Loureiro, Pascais, Romelle y Suñide.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','iglesia','Real Monasterio de San Julián de Samos','colosal e imponente complejo monástico benedictino fundado en el siglo VI que exhibe una majestuosa fachada barroca del siglo XVIII con escalinata monumental de sillería granítica berroqueña, el grandioso Claustro Grande o de Feijoo y la iglesia abacial de planta basilical.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','iglesia','Capilla del Ciprés (Capilla de San Salvador)','joya cumbre de la arquitectura mozárabe del siglo X construida extramuros del monasterio que destaca por sus reducidas dimensiones, sus muros de lajas de pizarra rústica tallada, su arco de herradura califal interior y un ciprés milenario catalogado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','iglesia','Iglesia de Santiago de Pascais','templo de origen románico profundamente reformado en época barroca que conserva de su fábrica medieval un ábside','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','monumento','Núcleos de población de O Saviñao','El término municipal incluye los siguientes núcleos de población: Diomondi, Marrube, Mourelos, Reiriz, Rosende, Seteventos y Vilaesteva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','iglesia','Iglesia de San Paio de Diomondi','joya cumbre del románico de la Ribeira Sacra de finales del siglo XII declarada Monumento Nacional que destaca por su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','iglesia','Iglesia de Santo Estevo de Ribas de Miño','monumental templo románico del siglo XII colgado de forma estratégica sobre los bancales del río Miño que presenta una fachada con un espectacular rosetón calado de sillería granítica gálica y una cripta absidial para salvar el desnivel rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','palacio','Pazo de de Rosende','gran conjunto palaciego barroco del siglo XVII de planta en U reconvertido que exhibe una fachada monumental de sillería granítica perfectamente labrada con los blasones heráldicos familiares, amplias solainas sobre robustas columnas y chimeneas monumentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','monumento','Castro de Abuíme','poblado fortificado prehistórico de la Edad del Hierro que conserva intacto su imponente sistema defensivo de varias murallas concéntricas de mampostería en seco de pizarra y cuarcita local junto a las bases de varias viviendas indígenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','monumento','Núcleos de población de Sober','El término municipal incluye los siguientes núcleos de población: Amandi, Bolmente, Doade, Lobios, Proendos y Santiorxo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','iglesia','Iglesia de San Juan de Amandi','obra cumbre del románico rural gallego del siglo XII que destaca por su monumental ábside semicircular de sillería de granito gálica con una galería de arquerías ciegas sobre columnas adosadas y capiteles historiados de exquisita finura iconográfica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','iglesia','Santuario de Nuestra Señora de Cadeiras','templo de peregrinación barroco del siglo XVIII colgado sobre los espectaculares cañones del Sil que presenta una fachada neoclásica simétrica de cantería regular, su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','monumento','Yacimiento Romano de Proendos','complejo arqueológico musealizado que conserva los restos de una importante villa residencial romana del siglo III con piletas destinadas a la producción vinícola tradicional, bases de columnas de granito y canalizaciones hidráulicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','palacio','Pazo de de de de de Conde','gran residencia hidalga del siglo XVII que presenta una fisionomía maciza fortificada con gruesos muros de piedra, ventanas saeteras defensivas, portalón de acceso con un escudo de armas familiar labrado y una solaina sobre robustas pilastras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','monumento','Núcleos de población de Xove','El término municipal incluye los siguientes núcleos de población: Lago, Morás, Portocelo, Sumoas y Xuances.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','palacio','Pazo de de Sumoas','gran residencia palaciega barroca del siglo XVII construida en sólida sillería de granito y losas de pizarra rústica que destaca por su portalón fortificado flanqueado por pináculos heráldicos, amplias solainas sobre columnas toscanas y un palomar circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','iglesia','Iglesia de San Pedro de Xuances','templo de origen románico profundamente modificado en el siglo XVIII que conserva de su fábrica medieval el ábside rectangular de cantería regular perfecta y una valiosa serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','monumento','Conjunto Etnográfico de los Molinos de Morás','agrupación de arquitectura popular e industrial hidráulica menor que reúne varios molinos harineros de agua construidos en mampostería granítica alineados junto al cauce fluvial para el aprovechamiento de la fuerza hidráulica de los riachuelos costeros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','monumento','Núcleos de población de Taboada','El término municipal incluye los siguientes núcleos de población: Bembibre, Castelo, Esperante, Insua, Mato, Piñeira y Taboada dos Freires.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','iglesia','Iglesia de San Tomé de de Taboada dos Freires','joya monumental del románico de finales del siglo XII labrada por el maestro Pelagio que destaca por su portada occidental de arquivoltas profundas con un tímpano esculpido con la escena de Sansón y el león.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','palacio','Pazo de de Bembibre','monumental conjunto palaciego barroco del siglo XVII de planta en U que exhibe una fachada monumental de sillería granítica perfectamente labrada con los blasones heráldicos de los llinajes gallegos, grandes chimeneas y una torre defensiva desmochada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','iglesia','Iglesia de Santa María de de Castelo','edificación románica de finales del siglo XII colgada sobre la ladera que presenta una planta de nave única con ábside semicircular de sillería regular y una excelente serie de canecillos esculpidos con temática zoomorfa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','monumento','Núcleos de población de Triacastela','El término municipal incluye los siguientes núcleos de población: Alvareda, Cancelo, Pasantes, Santalla y Vilavella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','iglesia','Iglesia de Santiago de Triacastela','templo de origen románico profundamente reformado en el siglo XVIII estrechamente vinculado al Camino de Santiago Francés que destaca por su torre campanario barroca de sillería caliza calavera, cuya fachada exhibe un relieve pétreo con tres castillos tallados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','monumento','Cueva de de Eirós','extraordinario yacimiento arqueológico musealizado que conserva niveles de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','monumento','Caserío y Hospital de Vilavella','conjunto arquitectónico tradicional de mampostería de pizarra rústica y cuarcita local que albergó un antiguo hospital de peregrinos medieval, conservando portadas adinteladas de piedra y hórreos tradicionales lucenses de tipo mixto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','monumento','Núcleos de población de Vilalba','El término municipal incluye los siguientes núcleos de población: Alba, Belesar, Insua, Mourence, Nete, Oleiros, San Simón da Costa y Santaballa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','monumento','Torre del Homenaje de Vilalba (Castillo de los Andrade)','imponente baluarte fortificado de planta octogonal perteneciente a la antigua fortaleza medieval del siglo XIV que se eleva en el centro de la villa con potentes lienzos de sillería granítica y matacanes defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','iglesia','Iglesia de Santa María de de Vilalba','monumental templo parroquial edificado en el siglo XVIII sobre traza neoclásica que presenta una imponente fachada de cantería regular flanqueada por dos esbeltas torres gemelas y un interior espacioso de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','palacio','Pazo de de de Penas-Corveira','gran residencia hidalga del siglo XVII que presenta una fisionomía maciza construida en sólida sillería granítica con un monumental portalón de acceso adintelado, grandes escudos nobiliarios labrados en piedra noble y amplias galerías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','monumento','Puente de de de Saa (Belesar)','estructura civil medieval construida sobre los cimientos de una antigua calzada que salva el cauce del río Magdalena mediante arcos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27021','monumento','Núcleos de población de Xermade','El término municipal incluye los siguientes núcleos de población: Burgás, Cabreiros, Candamil, Lousada, Miraz y Momán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27021','iglesia','Iglesia de Santa María de de Cabreiros','edificación religiosa del siglo XVIII adscrita al barroco rural de montaña que cuenta con muros de mampostería granítica vista, una portada de arco de medio punto rematada por una hornacina y una esbelta espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27021','palacio','Pazo de de Miraz','casona solariega fortificada de los siglos XVI y XVII que presenta una fisionomía maciza de muros de piedra pizarra, ventanas saeteras defensivas, portalón de acceso con un escudo de armas familiar labrado y una solaina sobre robustas pilastras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27021','monumento','Cruceiro de Candamil','monumento etnográfico exento del siglo XIX labrado en granito por maestros canteros locales que muestra un pedestal moldurado sobre tres gradas cuadradas, fuste estriado y una cruz superior ornamentada con las figuras de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','monumento','Núcleos de población de Cabanas','El término municipal incluye los siguientes núcleos de población: Laraxe, Regoela, San Martiño de Porto, Santa Cruz do Salto y Soaserra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','monumento','Puente Medieval sobre el Río Eume','monumental paso civil reconstruido en el siglo XIV por orden de Fernán Pérez de Andrade que une Cabanas y Pontedeume, conservando de su fábrica histórica pilastras masivas de sillería granítica berroqueña calzadas en el estuario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','iglesia','Iglesia de San Martiño de de de Porto','templo de origen románico profundamente modificado en el siglo XVIII que destaca por su fachada barroca de cantería vista con hornacina central para el santo patrón, cornisa moldurada de doble pináculo y una esbelta torrecampanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','palacio','Pazo de de de Frais','gran residencia hidalga del siglo XVII de planta rectangular que presenta una fisionomía maciza construida con aparejo granítico regular, provista de un portalón de acceso flanqueado por pináculos heráldicos y amplias solainas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','monumento','Núcleos de población de Carballo','El término municipal incluye los siguientes núcleos de población: Aldemunde, Ardaña, Berdillo, Entrecruces, Rus, Sofán y Sísamo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','iglesia','Iglesia de San Martiño de Razo','templo de origen románico del siglo XII profundamente reformado en el barroco que conserva de su fábrica medieval el ábside rectangular de sillería isódoma perfecta, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','palacio','Pazo de Gontade','casona solariega barroca del siglo XVIII construida con aparejo regular de granito del país que exhibe una fachada monumental provista de grandes escudos heráldicos de los llinajes locales, amplias balconadas de forja gallega y una escalinata interior de piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','monumento','Antiguo Balneario de Carballo','pabellón termal de arquitectura decimonónica clasicista del siglo XIX construido en cantería vista que conserva sus salas de baños originales con arquerías de medio punto, grandes vanos acristalados y un entorno ajardinado diseñado junto al manantial medicinal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Núcleos de población de A Coruña','El término municipal incluye los siguientes núcleos de población: Elviña, Feáns, Mesoiro, San Cristóbal de las Viñas y Visma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Torre de Hércules','colosal faro de origen romano construido a finales del siglo I bajo el imperio de Trajano que está declarado Patrimonio de la Humanidad por la UNESCO al conservar su núcleo estructural de sillería isódoma granítica berroqueña revestido por una monumental fachada neoclásica del siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','iglesia','Colegiata de Santa María del Campo','magno templo del gótico marinero de transición construido entre los siglos XII y XIV que destaca por su severa portada occidental provista de un magnífico rosetón calado de sillería granítica gálica y un tímpano esculpido con la Adoración de los Reyes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','iglesia','Iglesia de Santiago','el templo religioso más antiguo del casco urbano edificado en estilo románico tardío del siglo XII que exhibe una monumental fachada con portada de arquivoltas profundas apuntadas sobre capiteles historiados, un tímpano con la figura de Santiago Apóstol y un ábside semicircular perfecto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Castillo de San Antón','imponente fortaleza marítima defensiva del siglo XVI emplazada sobre un islote que conserva sus gruesos baluartes de sillería granítica berroqueña, casamatas abovedadas, garitas de vigilancia fortificadas y un aljibe subterráneo excavado en la roca madre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Yacimiento Arqueológico del Castro de Elviña','colosal poblado fortificado de la Edad del Hierro y época romano-gala musealizado que preserva sus potentes lienzos de muralla defensiva perimetral de mampostería en seco junto a la estructura de la denominada "Casa del Tesoro" y pozos hidráulicos monumentales. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','iglesia','La Iglesia de Santa Maria d''Arenys','La Iglesia de Santa Maria d''Arenys (siglos XVI-XVIII) es un edificio de transición renacentista y barroca construido en sillería de granito que alberga el retablo mayor barroco de Pau Costa, obra cumbre tallada en madera dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','monumento','Las Torres de Defensa Urbanas','Las Torres de Defensa Urbanas (Torre dels Encantats, Torre de Llobet) (siglo XVI) son estructuras militares cilíndricas y cuadrangulares levantadas en mampostería de granito para repeler las incursiones de la piratería berberisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','monumento','El Cementerio de Sinera','El Cementerio de Sinera (siglo XIX-XX) es un hito monumental modernista y neogótico edificado con panteones esculpidos en mármol de Carrara y piedra de Montjuïc por escultores como Josep Llimona y Venanci Vallmitjana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','monumento','El Mercat Municipal d''Arenys','El Mercat Municipal d''Arenys (año 1925) es una nave de estilo modernista industrial edificada por Ignasi Mas en ladrillo visto rojo, piedra labrada y elementos ornamentales de hierro fundido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90558','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90558','iglesia','La Iglesia de Sant Martí d''Arenys de Munt','La Iglesia de Sant Martí d''Arenys de Munt (siglo XVI) es un templo de tipología gótica tardía edificado en cantería de granito local que destaca por su ábside poligonal y un retablo renacentista de Pere Serafí.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90558','monumento','El Castell de Jalpí','El Castell de Jalpí (siglo XIX-XX) es una residencia señorial historicista que reformó una antigua masía medieval del siglo XIV utilizando muros almenados, torres de mampostería caliza y carpinterías de roble noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90558','ermita','La Ermita de la Mare de Déu de Lourdes','La Ermita de la Mare de Déu de Lourdes (año 1928) es un santuario popular de estilo neogótico integrado en un entorno natural boscoso empleando piedra basta rústica y arcos apuntados de cemento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90559','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90559','monumento','El Castillo de Argençola','El Castillo de Argençola (siglo XI) representa las ruinas de una fortaleza de la Marca de Berga de la que resta una torre de planta circular levantada en sillarejo de piedra calcárea de la Anoia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90559','iglesia','La Iglesia de Santa Maria de Clariana','La Iglesia de Santa Maria de Clariana (siglo XII) es una construcción de tipología románica rural edificada en sillería irregular caliza con una nave cubierta por bóveda de cañón apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90560','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90560','iglesia','La Iglesia de Sant Julià d''Argentona','La Iglesia de Sant Julià d''Argentona (siglo XVI) es un templo de estilo gótico tardío modificado por Josep Puig i Cadafalch, levantado en sillería de granito con una gran portalada y vidrieras historicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90560','monumento','La Casa Garí','La Casa Garí (año 1898) es un palacete residencial modernista diseñado por Josep Puig i Cadafalch mediante la reforma de una antigua masía, utilizando estucos, azulejos polícromos, sillería caliza y forja artística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90560','iglesia','La Capilla de Sant Pere de Clarà','La Capilla de Sant Pere de Clarà (siglo XII) es una ermita románica benedictina de una sola nave construida con aparejo rústico de piedra de río y sillares bien tallados en las esquinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90560','monumento','El Museu del Càntir d''Argentona','El Museu del Càntir d''Argentona (siglo XX) es una infraestructura cultural que protege la colección etnográfica de alfarería tradicional más importante del territorio peninsular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90561','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90561','iglesia','La Iglesia de Sant Vicenç d''Obiols','La Iglesia de Sant Vicenç d''Obiols (siglos VIII-X) es un templo prerrománico de influencia visigótica y mozárabe edificado en grandes sillares irregulares de piedra caliza con un ábside trapezoidal y arcos de herradura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90561','iglesia','La Iglesia de Santa Maria d''Avià','La Iglesia de Santa Maria d''Avià (siglo XII) es una obra cumbre del románico del Berguedà levantada en sillería regular caliza que albergaba el famoso frontal de altar pintado sobre madera del siglo XIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90561','monumento','La Colonia Industrial de Cal Rosal','La Colonia Industrial de Cal Rosal (siglo XIX) es un inmenso complejo textil del patrimonio manufacturero catalán construido junto al río Llobregat con naves de mampostería, ladrillo visto y turbinas hidráulicas de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90562','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90562','iglesia','La Iglesia de Sant Joan d''Avinyó','La Iglesia de Sant Joan d''Avinyó (siglos XII-XVII) presenta restos de su origen románico en la fachada oeste, estando reconstruida en estilo barroco con sillería de arenisca y una esbelta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90562','iglesia','La Iglesia de Santa Eugènia de Relat','La Iglesia de Santa Eugènia de Relat (siglo XII) es un templo románico rural de planta basilical con ábside semicircular edificado con aparejo de sillarejo de piedra caliza del Bages.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90562','monumento','El Pont Vell d''Avinyó','El Pont Vell d''Avinyó (siglo XIV) es un puente gótico de tres arcos apuntados construido sobre el río Gavarresa utilizando sillería regular de arenisca para el tránsito ganadero tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','iglesia','El Monasterio de Sant Sebastià dels Gorgs','El Monasterio de Sant Sebastià dels Gorgs (siglo XI) es un antiguo priorato benedictino que conserva un claustro románico con capiteles ricamente esculpidos y una torre campanario levantada en sillería caliza fina del Penedès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','monumento','El Conjunto Monumental de las Gunyoles','El Conjunto Monumental de las Gunyoles (siglos XIVXVII) destaca por su torre de defensa señorial de planta cilíndrica y casonas construidas con mampostería caliza y portadas de medio punto de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','monumento','La Yacimiento Arqueológico de la Font de la Canya','La Yacimiento Arqueológico de la Font de la Canya (siglos VII-III a.C.) es un asentamiento ibérico fortificado clave para la historia de la agricultura donde se documentaron las semillas de viña más antiguas de Cataluña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Alpens Alpens 281 L''Ametlla de...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','monumento','El Yacimiento de la Ciudad Romana de Baetulo','El Yacimiento de la Ciudad Romana de Baetulo (siglo I a.C.) constituye un inmenso complejo arqueológico subterráneo que conserva las termas, el decumanus y tiendas edificadas en sillería caliza y opus caementicium.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','iglesia','La Iglesia de Santa Maria de Badalona','La Iglesia de Santa Maria de Badalona (siglo XVIII) es un templo barroco clasicista levantado en sillería de piedra caliza de Montjuïc sobre los restos de un templo romano anterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','iglesia','El Monasterio de San Jerónimo de la Murtra','El Monasterio de San Jerónimo de la Murtra (siglo XV) es un cenobio gótico mandado edificar por los reyes católicos que destaca por su claustro de dos plantas labrado en piedra caliza fina con capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08002','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08002','iglesia','La Iglesia de Sant Esteve de Bagà','La Iglesia de Sant Esteve de Bagà (siglos XIV-XV) es un gran templo de transición del románico al gótico edificado en sillería caliza gris que presenta una nave monumental con bóvedas de crucería y un ábside poligonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08002','palacio','El Palacio de los Pinós','El Palacio de los Pinós (siglo XIV) es una fortaleza señorial fortificada construida en mampostería de caliza del Berguedà estructurada en torno a un patio de armas que aloja pinturas murales góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08002','monumento','El Pórtico de la Plaza Galceran de Pinós','El Pórtico de la Plaza Galceran de Pinós (siglo XIII) constituye un conjunto urbano preindustrial único en el Pirineo con calles empedradas y arcos de medio punto levantados con sillería de piedra calcárea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90564','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90564','iglesia','La Iglesia de Sant Fructuós de Balenyà','La Iglesia de Sant Fructuós de Balenyà (siglo XII-XVII) es un edificio de origen románico transformado en el período barroco, levantado en sillarejo de piedra arenisca de la Plana de Vic con un comunidor exento en su cementerio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90564','iglesia','El Santuario de la Mare de Déu de l''Ajuda','El Santuario de la Mare de Déu de l''Ajuda (siglo XIVXVIII) es un templo gótico y barroco edificado en mampostería encintada que conserva un campanario medieval fortificado con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90565','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90565','monumento','El Castillo de Balsareny','El Castillo de Balsareny (siglo XIV) es una fortaleza gótica de planta rectangular perfecta y tipología palaciega, edificada con sillería regular de piedra caliza gris de la cuenca del Bages rodeando un patio central con cisterna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90565','iglesia','La Iglesia de Santa Maria de Balsareny','La Iglesia de Santa Maria de Balsareny (siglo XIII) es un templo de traza románica tardía con reformas góticas posteriores, construido con muros de sillería de arenisca y una bóveda de cañón apuntada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90565','monumento','La Acequia de Manresa','La Acequia de Manresa (Séquia de Manresa) (siglo XIV) es una monumental infraestructura de ingeniería hidráulica preindustrial que arranca en la esclusa de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','catedral','La Catedral de la Santa Cruz y Santa Eulalia','La Catedral de la Santa Cruz y Santa Eulalia (siglos XIII-XV) es la sede monumental del gótico barcelonés, edificada en sillería de piedra arenisca de Montjuïc con tres naves de gran altura, girola con capillas y un claustro arbolado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','iglesia','La Basílica de Santa Maria del Mar','La Basílica de Santa Maria del Mar (siglo XIV) representa la pureza del gótico catalán, promovida por los gremios de la Ribera y ejecutada por Berenguer de Montagut empleando bloques de sillería regular de Montjuïc para sus esbeltos pilares octogonales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','palacio','El Palacio de la Generalidad de Cataluña','El Palacio de la Generalidad de Cataluña (siglos XVXVII) es un complejo institucional civil que integra una fachada renacentista de Pere Blai hecha en sillería caliza, un patio gótico flamígero y la capilla de Sant Jordi.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','iglesia','El Templo Expiatorio de la Sagrada Familia','El Templo Expiatorio de la Sagrada Familia (año 1882en desarrollo) es la obra cumbre del modernismo catalán diseñada por Antoni Gaudí, estructurada como una basílica orgánica mediante el uso de hormigón armado, granito, pórfido y arenisca de Montjuïc.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','monumento','El Hospital de la Santa Cruz y San Pablo','El Hospital de la Santa Cruz y San Pablo (año 1902) es un inmenso conjunto hospitalario modernista proyectado por Lluís Domènech i Montaner utilizando pabellones exentos de ladrillo visto rojo, azulejos de cerámica vidriada policromada y esculturas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90566','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90566','iglesia','La Iglesia Vieja de Sant Cristòfol','La Iglesia Vieja de Sant Cristòfol (siglo XVI) es un templo gótico arcaizante de montaña edificado con paramentos de mampostería de piedra caliza del macizo del Garraf y una torre campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90566','monumento','El Yacimiento de la Cueva de Can Sadurní','El Yacimiento de la Cueva de Can Sadurní (Epipaleolítico-Neolítico) constituye una cueva calcárea de gran relevancia arqueológica donde se documentaron las evidencias de procesado y consumo de cerveza más antiguas del continente europeo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90567','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90567','monumento','El Castillo de Queralt','El Castillo de Queralt (siglo X) representa las ruinas de una fortaleza fronteriza de la Marca Hispánica levantada en sillarejo de piedra caliza de la Anoia que conserva la base de una torre circular y la iglesia románica de Sant Cristòfol.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90567','iglesia','La Iglesia de Sant Salvador de Bellprat','La Iglesia de Sant Salvador de Bellprat (siglo XVII) es un templo barroco rural construido en mampostería irregular con esquinales de cantería y un campanario de espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','monumento','El Castillo de San Fernando o de la Pica','El Castillo de San Fernando o de la Pica (siglos XIIXIX) es una fortaleza militar reformada para la artillería carlista, construida con gruesos baluartes de mampostería caliza aprovechando la roca natural del Berguedà.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','iglesia','La Iglesia Parroquial de Santa Eulàlia','La Iglesia Parroquial de Santa Eulàlia (siglo XVII) es un gran edificio barroco clasicista diseñado por el arquitecto Josep Morató empleando sillería regular de piedra caliza con una nave monumental y capillas laterales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','iglesia','El Santuario de Nuestra Señora de Queralt','El Santuario de Nuestra Señora de Queralt (siglo XVIII) es un complejo religioso neoclásico colgado sobre la sierra a más de mil metros de altitud, edificado con paramentos de mampostería basta y sillería en los accesos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','iglesia','La Iglesia de Sant Quirze de Pedret','La Iglesia de Sant Quirze de Pedret (siglos IX-X) es una joya del arte prerrománico y mozárabe situada en el término histórico, construida en sillarejo rústico con arcos de herradura y un ábside trapezoidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90568','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90568','iglesia','El Monasterio de Sant Miquel del Fai','El Monasterio de Sant Miquel del Fai (siglo XI) es un cenobio cenobítico románico construido de forma inverosímil bajo un gran abrigo de roca de toba calcárea','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90568','monumento','El Castillo de Montbui','El Castillo de Montbui (siglo X) son las ruinas de una edificación militar defensiva construida con aparejo rústico y argamasa que conserva la planta de su capilla románica de Sant Mateu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90568','iglesia','La Iglesia de Sant Pere de Bigues','La Iglesia de Sant Pere de Bigues (siglo XVI-XVIII) es un templo barroco edificado en mampostería con una fachada sobria y esquinales de sillería de piedra arenisca del Vallès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90569','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90569','iglesia','La Iglesia de Santa Maria de Borredà','La Iglesia de Santa Maria de Borredà (siglo XII) es un edificio románico de planta basilical modificado en el barroco, levantado en sillería regular de piedra caliza gris con una portada de arquivoltas lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90569','iglesia','La Iglesia de Sant Sadurní de Rotgers','La Iglesia de Sant Sadurní de Rotgers (siglo XII) es una de las obras más puras del románico rural del Berguedà, edificada en perfecto sillarejo con un ábside semicircular y una torre campanario sobrealzada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90570','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90570','iglesia','La Iglesia de Santa Maria del Bruc','La Iglesia de Santa Maria del Bruc (siglos XII-XVIII) presenta un origen románico visible en su ábside de sillería con arcuaciones lombardas, ampliado en época barroca con mampostería y ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90570','monumento','Las Ruinas del Castillo de la Guàrdia','Las Ruinas del Castillo de la Guàrdia (siglo X) constituyen los restos de una fortaleza de la Marca del Penedès alzada con bloques de piedra conglomerada calcárea de la montaña de Montserrat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90570','monumento','El Monumento a los Héroes del Bruc','El Monumento a los Héroes del Bruc (año 1952) es un hito conmemorativo de la Guerra de la Independencia esculpido por Frederic Marès utilizando bloques de piedra calcárea de Montserrat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90571','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90571','monumento','El Castillo del Brull','El Castillo del Brull (siglo X-XII) representa las ruinas de una fortaleza monumental de la que se conserva una gran torre de planta circular levantada en sillería de piedra calcárea del Montseny.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90571','iglesia','La Iglesia de Sant Martí del Brull','La Iglesia de Sant Martí del Brull (siglo XI) es un templo románico lombardo edificado en sillarejo regular con un ábside decorado con lesenas y un friso de arcos ciegos que aloja pinturas murales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90571','monumento','La Muralla Ibérica del Turó de Montgròs','La Muralla Ibérica del Turó de Montgròs (siglos IV-III a.C.) es una impresionante fortificación preindustrial construida con una doble línea de grandes bloques de piedra basta sin argamasa para cerrar el paso al macizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08029','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08029','monumento','El Castillo de Burriac','El Castillo de Burriac (siglos XII-XV) es una fortificación militar gótica alzada sobre una colina cónica con sillería y mampostería de granito local que conserva su torre de homenaje circular y el recinto amurallado jalonado de saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08029','monumento','El Yacimiento Arqueológico de Ca l''Arnau - Can Mateu','El Yacimiento Arqueológico de Ca l''Arnau - Can Mateu (siglo II a.C.) constituye un complejo residencial e industrial romano de época republicana que conserva las termas públicas más antiguas de la península edificadas con opus caementicium y pavimentos de opus signinum.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08029','iglesia','La Iglesia de Sant Feliu de Cabrera','La Iglesia de Sant Feliu de Cabrera (siglo XVI) es un edificio de tipología gótica tardía edificado en cantería de granito con una nave única, capillas laterales integradas y una portada esculpida con motivos flamígeros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08030','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08030','iglesia','La Iglesia Parroquial de Santa Creu','La Iglesia Parroquial de Santa Creu (siglo XVIII) es un templo barroco edificado en mampostería de granito y arenisca con una fachada sobria rematada en hornacina y un campanario de torre cuadrangular con cúpula baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08030','monumento','El Conjunto de Torres de Defensa Civiles','El Conjunto de Torres de Defensa Civiles (Torre de Can Amat, Torre de Ca n''Oliver) (siglo XVI) agrupa estructuras cuadrangulares integradas en masías tradicionales, levantadas en mampostería rústica para proteger a la población de las razzias berberiscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08031','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08031','monumento','El Castillo de Calaf','El Castillo de Calaf (siglo XI-XIV) representa las ruinas consolidadas de una imponente fortaleza de la Marca del condado de Manresa, estructurada con potentes muros poligonales de sillería caliza y una torre maestra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08031','iglesia','La Iglesia de Sant Jaume de Calaf','La Iglesia de Sant Jaume de Calaf (siglo XVII) es una obra monumental del gótico tardío y el estilo barroco civil catalán, levantada en sillería caliza de la Alta Anoia con una cripta subterránea y un campanario octogonal de treinta y ocho metros de altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08031','monumento','La Plaza Grande Porchada','La Plaza Grande Porchada (siglos XV-XVII) constituye el núcleo logístico preindustrial del mercado histórico de la villa, caracterizado por sus soportales sostenidos por columnas de piedra labrada y capiteles heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08034','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08034','monumento','El Castillo de Calders','El Castillo de Calders (siglo XI) son los restos de una fortificación medieval edificada sobre un meandro del río Calders empleando sillarejo regular calizo para su torre de homenaje circular y el lienzo defensivo perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08034','iglesia','La Iglesia de Sant Vicenç de Calders','La Iglesia de Sant Vicenç de Calders (siglos XI-XVIII) conserva la cabecera barroca y esquinales de sillería arenisca que sustituyeron al templo románico primitivo, del cual perduran paramentos de sillarejo lombardo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08034','monumento','La Colonia Industrial de Jorba','La Colonia Industrial de Jorba (siglo XIX) es un conjunto fabril textil situado junto al río Calders con naves longitudinales de mampostería, chimenea de ladrillo prensado e infraestructuras de canalización hidráulica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','iglesia','La Iglesia de Santa Maria i Sant Nicolau','La Iglesia de Santa Maria i Sant Nicolau (siglo XVIII) es un gran templo barroco clasicista diseñado por el arquitecto Josep Morató, construido en sillería de granito del Maresme con una portada monumental ornada con hornacinas y relieves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','monumento','Las Torres de Telegrafía Óptica','Las Torres de Telegrafía Óptica (Les Torretas) (año 1849) son dos torres militares de planta cuadrangular edificadas en mampostería y ladrillo macizo para la red de comunicaciones del Estado civil y militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','monumento','El Faro de Calella','El Faro de Calella (año 1859) es una infraestructura logística marítima construida sobre un promontorio rocoso con piedra granítica labrada y un cuerpo cilíndrico rematado por linterna de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08037','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08037','iglesia','La Iglesia de Sant Martí de Riudeperes','La Iglesia de Sant Martí de Riudeperes (siglo XI-XVIII) es un edificio de origen románico lombardo ampliado en el período barroco con muros de mampostería y cantería de piedra arenisca de la Plana de Vic.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08037','iglesia','El Monasterio de Sant Tomàs de Riudeperes','El Monasterio de Sant Tomàs de Riudeperes (siglo XIXVI) es un antiguo cenobio agustiniano que conserva un claustro renacentista de dos pisos ejecutado en cantería caliza fina con arquerías de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08036','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08036','monumento','El Castillo de Calonge','El Castillo de Calonge (siglo XI) son las ruinas de una fortaleza del Condado de Cardona edificada con aparejo regular de sillería caliza que conserva elementos arquitectónicos de planta semicircular y bóvedas de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08036','iglesia','La Iglesia de Santa Fe de Calonge','La Iglesia de Santa Fe de Calonge (siglo XII) es un templo románico de una sola nave con ábside semicircular decorado con arquillos ciegos lombardos ejecutados en piedra calcárea de la Segarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08036','iglesia','La Iglesia de Santa Maria de Mirambell','La Iglesia de Santa Maria de Mirambell (siglo XII) presenta una tipología románica rural construida en sillarejo irregular con esquinales reforzados y una portada lateral con arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08041','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08041','iglesia','La Iglesia de Feliu de Canovelles','La Iglesia de Feliu de Canovelles (siglo XI) es una joya del románico lombardo del Vallès Oriental, levantada en sillería regular y sillarejo de piedra arenisca con un ábside decorado con lesenas y un notable porche gótico posterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08041','monumento','Can Marques d''Amunt','Can Marques d''Amunt (siglos XVI-XVII) es una gran masía señorial de tipología etnográfica construida con muros portantes de mampostería mixta, ventanas con dinteles góticos labrados en piedra y portón dovelado de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08044','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08044','monumento','El Yacimiento Arqueológico del Abric Romaní','El Yacimiento Arqueológico del Abric Romaní (Paleolítico Medio) constituye uno de los enclaves musterienses más importantes del mundo, localizado en un nicho de toba calcárea (travertino) con restos de hogares y herramientas paleolíticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08044','monumento','El Molino Papelero de la Vila','El Molino Papelero de la Vila (Molí Paperer) (siglo XVIII) es un monumental edificio industrial e hito etnográfico erigido en mampostería y entramados de madera para la fabricación artesanal de papel utilizando la energía hidráulica de la balsa de Capellades.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08044','iglesia','La Iglesia de Santa Maria de Capellades','La Iglesia de Santa Maria de Capellades (siglo XVIIIXIX) es un edificio neoclásico de planta de cruz latina edificado en ladrillo y sillería caliza fina con una gran cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08045','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08045','iglesia','La Iglesia de Sant Salvador de Capolat','La Iglesia de Sant Salvador de Capolat (siglo XII) es una ermita románica rural de montaña levantada en sillería irregular caliza sobre una planicie rocosa del Berguedà con bóveda de cañón apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08045','iglesia','El Santuario de los Tossals','El Santuario de los Tossals (siglo XVIII) representa las ruinas de un complejo conventual franciscano situado a gran altitud, edificado con muros toscos de mampostería caliza rústica y mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08045','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Caldes d''Estrac Caldetas 3148 ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','monumento','El Castillo de Cardona','El Castillo de Cardona (siglos XI-XV) es una imponente fortaleza ducal y baluarte abaluartado góticorenacentista, edificado con sillería de piedra caliza y arenisca local en lo alto de un cerro estratégico que domina el valle del Cardener.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','iglesia','La Colegiata de San Vicente de Cardona','La Colegiata de San Vicente de Cardona (siglo XI) representa la obra cumbre del primer románico lombardo catalán, promovida por el vizconde Bermundo y ejecutada enteramente en sillería regular caliza con una gran nave central de tres tramos y cripta bajo el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','iglesia','La Iglesia de San Miguel de Cardona','La Iglesia de San Miguel de Cardona (siglo XIV) es un templo de tipología gótica meridional catalana que cuenta con una amplia nave única, capillas laterales entre los contrafuertes y un coro alto, levantado en sillería regular de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','monumento','El Parque Cultural de la Montaña de Sal','El Parque Cultural de la Montaña de Sal (siglos I a.C.XX) constituye un hito geológico e industrial minero explotado desde época romana que conserva pozos de extracción de sal gema e infraestructuras de castilletes construidas en hierro remachado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08048','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08048','iglesia','La Iglesia Parroquial de San Martín','La Iglesia Parroquial de San Martín (siglo XVIII) es un edificio de tipología barroca tardía con fachada neoclásica, construido en mampostería de caliza de la Anoia y esquinales de sillería con un campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90572','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90572','iglesia','La Iglesia de San Pablo de Casserres','La Iglesia de San Pablo de Casserres (siglo XII) es un templo románico edificado en sillería de piedra caliza que destaca por su ábside semicircular con decoración de arcuaciones lombardas y por conservar restos de pinturas murales góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90572','monumento','La Colonia Industrial de l''Ametlla de Casserres','La Colonia Industrial de l''Ametlla de Casserres (siglo XIX) es un núcleo fabril textil fundado junto al río Llobregat con una gran fábrica de mampostería, chimenea de ladrillo prensado e iglesia neogótica diseñada por Alexandre Soler.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08057','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08057','iglesia','La Iglesia de San Vicente de Castell de l''Areny','La Iglesia de San Vicente de Castell de l''Areny (siglo XII) es una edificación románica de montaña levantada en sillarejo de piedra caliza gris del Berguedà con bóveda de cañón y un campanario de espadaña modificado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08057','iglesia','La Iglesia de San Román de la Clusa','La Iglesia de San Román de la Clusa (siglo XII) presenta una traza románica rural aislada en el valle, construida con aparejo tosco de piedra caliza local y techumbre cubierta por gruesas losas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08050','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08050','iglesia','La Iglesia de San Lorenzo de dos Rocas','La Iglesia de San Lorenzo de dos Rocas (siglo XII) es un templo románico rural empotrado bajo una gran mole calcárea, edificado en sillarejo irregular con bóveda de medio cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08050','monumento','El Pi de les Tres Branques','El Pi de les Tres Branques (Monumento Natural e Histórico) constituye un símbolo etnográfico y cultural de los países de lengua catalana que conserva el tronco fosilizado de un pino monumental rodeado por un recinto de piedra caliza labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08051','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08051','monumento','El Castillo de Clasquerí o de Castellar','El Castillo de Clasquerí o de Castellar (siglo XIV) es una fortaleza señorial de estilo gótico restaurada en el siglo XIX, construida con mampostería y sillería de arenisca rodeando un patio central con ventanas trilobuladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08051','iglesia','La Iglesia de San Esteban de Castellar','La Iglesia de San Esteban de Castellar (año 1892) es conocida como la "Catedral del Vallès" por sus dimensiones neogóticas, edificada por el arquitecto Joan Martorell en ladrillo macizo, piedra caliza de Girona y vidrieras polícromas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08051','iglesia','La Iglesia de San Feliu del Racó','La Iglesia de San Feliu del Racó (siglo XI-XII) conserva una torre campanario románica de planta cuadrangular con arcos lombardos exenta del cuerpo del templo barroco posterior, levantada en sillarejo de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08052','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08052','iglesia','La Iglesia de Santa María de Castellar de n''Hug','La Iglesia de Santa María de Castellar de n''Hug (siglo XI) presenta una esbelta torre campanario de tipología románica lombarda con ventanas ajimezadas y friso de dientes de sierra, ejecutada en perfecto sillarejo calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08052','monumento','El Núcleo Etnográfico de Castellar de n''Hug','El Núcleo Etnográfico de Castellar de n''Hug (siglos XVII-XIX) es un conjunto de arquitectura tradicional pirenaica caracterizado por sus calles empedradas con cantos rodados, casas de mampostería caliza roja y cubiertas de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08053','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08053','monumento','El Castillo de Castellbell','El Castillo de Castellbell (siglo XIV) representa las ruinas de una fortaleza gótica señorial situada estratégicamente sobre un meandro del río Cardener, construida con sillería y mampostería caliza basta de Montserrat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08053','monumento','El Puente Viejo de Castellbell','El Puente Viejo de Castellbell (siglo XIV) es una monumental infraestructura gótica de cuatro grandes arcos apuntados levantada sobre el río Cardener utilizando sillería regular caliza calavera para resistir las riadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08054','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
